Ceviri.ekle("uk","olay",{
"OLAYLAR:1299-01:0":{"b": ["Заснування Османського бейліку", "9f0b7c0a"], "d": ["Те, що Осман Газі з племені кайи почав діяти самостійно в околицях Сьоґюта та Доманіча, вважають усталеною традиційною точкою відліку заснування Османської держави; деякі історики вважають справжнім переломним моментом перемогу під Бафеєм 1302 року. Завдяки своєму розташуванню на візантійському прикордонні бейлік швидко набирав силу через походи газі. У цих умовах, коли сельджуцька спадщина розпадалася, Осман Газі згуртував довкола себе ахі, газі та кочових туркменів; його зв'язок із шейхом Едебалі вважають основою духовної легітимності бейліку. Інші місця, приєднані тоді ж: Інеґьоль, Ярхісар.", "9d689d45"]},
"OLAYLAR:1326-04-06:0":{"b": ["Завоювання Бурси", "98c727fa"], "d": ["Бурса, яку роками тримали в блокаді, здалася Орхану Газі, що керував останнім етапом облоги; місто стало першою великою столицею бейліку. За переказом, звістку про завоювання донесли Осману Газі, який лежав на смертному одрі; згідно з його заповітом, Османа Газі поховали в Бурсі. Незабаром місто забудували мечетями, імаретами та медресе, і воно стало зразком раннього османського містобудування.", "9ede6ee9"]},
"OLAYLAR:1331-03-02:0":{"b": ["Завоювання Ізніка", "a846a811"], "d": ["Ізнік (Нікея), один із найважливіших візантійських центрів в Анатолії, після перемоги під Пелеканоном 1329 року втратив надію на опір і здався Орхану Газі. Тут було засновано перше османське медресе, і такі вчені, як Давуд аль-Кайсарі, почали викладати; місто стало центром науки раннього періоду. Церкву Святої Софії перетворили на мечеть, явивши ранній приклад завойовницької традиції.", "8fd3bfb5"]},
"OLAYLAR:1337-01-01:0":{"b": ["Завоювання Ізміта", "06a35035"], "d": ["З падінням Ізміта (Нікомедії) під османську владу перейшла й остання важлива візантійська фортеця на анатолійському боці; увесь півострів Коджаелі аж до протилежного від Константинополя берега став османською землею. Так бейлік, запанувавши над усім південним і східним узбережжям Мармурового моря, підготував підґрунтя для переходу в Румелію.", "f677745c"]},
"OLAYLAR:1352-03-01:0":{"b": ["Фортеця Чимпе — перехід у Румелію", "c2f0a07d"], "d": ["Сулейман-паша, син Орхана Газі, 1352 року зробив своєю базою фортецю Чимпе, віддану під час візантійської громадянської війни; після великого землетрусу в березні 1354 року, що зруйнував Галліполі, спорожнілі фортеці швидко укріпили, і півострів перетворили на постійний османський плацдарм. Цей крок, підкріплений переселенням туркменського населення з Анатолії, став початком присутності османів на європейському континенті, яка тривала понад 550 років.", "4857333a"]},
"OLAYLAR:1361-05-05:0":{"b": ["Завоювання Едірне", "2f54ebb0"], "d": ["Взяття Едірне (Адріанополя), ключового міста Фракії, визначило головну базу та напрямок балканських завоювань; дата завоювання в джерелах є предметом дискусій — між 1361 і 1369 роками. Невдовзі місто стало столицею, засвідчивши, що центр ваги держави перемістився в Румелію; воно залишалося престольним містом (пайтахтом) близько 90 років, аж до завоювання Константинополя.", "25bd644f"]},
"OLAYLAR:1362-03:0":{"b": ["Мурад I зійшов на престол", "f8d48a26"], "d": ["Мурад I (Худавендіґяр), який посів престол після смерті Орхана Газі, за 27 років правління перетворив державу з прикордонного бейліку на кістяк імперії. Запровадженням системи пенчик було закладено основу яничарського корпусу, поширено тімарну систему, засновано Румелійський бейлербейлік і зміцнено інститут візирату. За його правління балканські завоювання стали систематичною державною політикою.", "d463078a"]},
"OLAYLAR:1389-06-15:0":{"b": ["Перша Косовська битва — загибель Мурада I за віру", "10b8ddc9"], "d": ["Балканський союз на чолі з князем Лазарем зазнав вирішальної поразки на Косовому полі; Сербія перейшла під османський сюзеренітет. Мурада I, який оглядав поле бою, заколов кинджалом сербський шляхтич Милош Обилич, і султан загинув як шахід — це єдиний османський султан, який помер на полі бою. На його місце в таборі посадили Баязида Блискавичного (Йилдирима); його брата Якуба Челебі задушили, і це стало одним із перших відомих прикладів практики братовбивства.", "153449fe"]},
"OLAYLAR:1396-09-25:0":{"b": ["Перемога під Нікополем", "75716e96"], "d": ["Велике військо хрестоносців, зібране на заклик угорського короля Сигізмунда, до якого приєдналися й французькі та бургундські лицарі, Баязид Блискавичний вщент розгромив під Нікополем на березі Дунаю. Перемога остаточно закріпила османське панування над Болгарією; протягом цілого покоління в Європі не вдалося організувати великого хрестового походу.", "0d06e36c"]},
"OLAYLAR:1402-07-28:0":{"b": ["Анкарська битва — почалося Османське міжцарів'я", "b4a99d96"], "d": ["У тяжкій поразці від війська Тимура на Чубуцькій рівнині Баязид Блискавичний потрапив у полон і через кілька місяців помер у неволі. Тимур відродив анатолійські бейліки; османські землі поділили між собою сини Баязида, і почалася боротьба за престол, що тривала 11 років (міжцарів'я, Фетрет). Цей період, найтяжча криза держави від часу її заснування, закарбував в османській пам'яті важливість централізованого устрою. Інші поселення, втрачені тоді ж: Датча, Мармарис, Фетхіє (Макрі), Сьоке, Кютах'я, Афьон, Іспарта, Маніса, Айдин, Денізлі, Мугла, Анталія, Конья, Караман, Кайсері, Кастамону, Бартин, Сафранболу, Самсун, Сівас, Малатья, Бейшехір, Сіврігісар, Киршехір, Чорум, Чанкири, Єнішехір (Бурса), Інеґьоль, фортеця Айдос, Ґейве, Кьопрюхісар (Єнішехір), Мармараджик, Акхісар (Памукова), Мекедже, Кестель, Улубат, Харманкая, Акьязи, острів Імрали, Кандира, Муданья, Ялова, Карамюрсель, Армутлу, Гемлік (Кіос), Сьоґют, Біледжик, Ескішехір, Бурса, Ізнік, Ізміт, Баликесір, Чанаккале, Берґама, Амасья, Токат, Чорлу, Люлебургаз, Малкара, Кешан, Іпсала, Кілітбахір, Чірмен, Стара Загора (Ескі Заґра), Татарпазарджик, Іхтіман, Кюстендил, Петрич, Неврокоп (Гоце Делчев), Драма, Галліполі, Чимпе, Едірне, Дімотіка, Киркларелі, Текірдаг, Пловдив, Софія, Ніш, Відін, Тирново, Варна, Шумен, Силістра, Нікополь, Русе, Салоніки, Серрес, Кавала, Скоп'є, Бітола, Охрид, Лариса (Єнішехір), Трикала, Ламія (Іздін), Плевен, Комотіні, Біга, Доманіч, Куладжахісар, Караджахісар, Ярхісар, Дімбос, Кіте (Кете), Лефке (Османелі), Леблебіджіхісар, Карачепюш, Каратігін, Абсу (Гіпсу), Адранос (Орханелі), Пелеканон (Ескіхісар), Ґебзе, Хереке, Самандира, Кірмасті (М. Кемальпаша), Міхаліч (Караджабей), Констанца, Ґьолязи (Аполлонія).", "d34e55d5"]},
"OLAYLAR:1413-07-05:0":{"b": ["Мехмед Челебі відновив єдність", "03413dfd"], "d": ["Мехмед I, перемігши Мусу Челебі під Чамурлу в останньому зведенні рахунків між братами, об'єднав землі країни під єдиною владою; тому його вважають «другим засновником держави». За його правління було відновлено розхитаний державний лад, врівноважено відносини з анатолійськими бейліками, а в Румелії провадилася обережна мирна політика. Інші поселення на карті, що тоді ж повернулися з періоду міжцарів'я під османське управління: Абсу (Гіпсу), Адранос (Орханелі), Акхісар (Памукова).", "45315d2d"]},
"OLAYLAR:1416-05-01:0":{"b": ["Повстання шейха Бедреддіна", "e0a072ca"], "d": ["Релігійно-суспільний рух, що розгорнувся навколо шейха Бедреддіна, великого правознавця та суфія, який під час міжцарів'я обіймав посаду казаскера, спалахнув одночасно з повстаннями Бьорклюдже Мустафи в Карабуруні та Торлака Кемаля в Манісі. Повстання криваво придушили; Бедреддіна схопили в Делі-Ормані та стратили в Серресі. Ця подія як найраніше велике суспільне й махдистське повстання в османській історії залишила глибокий слід у літературі та історіографії.", "1cf72ec4"]},
"OLAYLAR:1444-11-10:0":{"b": ["Перемога під Варною", "f739eedc"], "d": ["Угорсько-польське військо хрестоносців, яке, порушивши Сеґедський договір, вирушило на південь, знищив під Варною Мурад II, що після зречення престолу повернувся на чолі війська; молодий король Владислав III загинув на полі бою. Перемога усунула останній великий шанс зовнішнього втручання, спрямованого на ліквідацію османської присутності на Балканах, і убезпечила шлях до завоювання Константинополя.", "43adf0fb"]},
"OLAYLAR:1448-10-17:0":{"b": ["Друга Косовська битва", "ebe0b662"], "d": ["Військо Яноша Гуняді, який прагнув помститися за Варну, Мурад II остаточно розгромив у запеклій триденній битві. Це була остання велика польова битва хрестоносців проти османів на Балканах; завдяки перемозі османське панування на південь від Дунаю утвердилося вже незворотно.", "ea3ae23b"]},
"OLAYLAR:1453-05-29:0":{"b": ["Завоювання Константинополя", "583d5e3e"], "d": ["Після облоги, що тривала п'ятдесят чотири дні (6 квітня–29 травня 1453), уранці 29 травня османське військо подолало мури й увійшло в місто; останній імператор Костянтин XI загинув у боях, і Східна Римська імперія, що проіснувала 1100 років, відійшла в історію. Молодий султан прийняв титул «Фатіх» (Завойовник), зробив місто столицею і перетворив Святу Софію на мечеть; незабаром місто відродили заселенням і відбудовою. За TDV, Силіврі та Візе були остаточно завойовані лише 1453 року; за статтею TDV про Лемнос, острів перейшов під османське управління одразу після завоювання і був залишений родині Ґаттілузіо за умови сплати данини. В атласі Силіврі, Візе та Лемнос з цього дня позначені як такі, що перейшли від Візантії до османів (Лемнос — як данник). Відливання велетенських гармат, перетягування кораблів суходолом та облоговий лад перед мурами вважають вершиною тогочасної військової інженерії. В європейській історіографії це завоювання належить до символічних дат кінця Середньовіччя.", "d4b39486"]},
"OLAYLAR:1461-08-15:0":{"b": ["Завоювання Трапезунда", "15f52403"], "d": ["Наприкінці важкого чорноморського походу, який Фатіх вів одночасно силами війська й флоту, Трапезундська імперія здалася; з ліквідацією цього останнього уламка візантійського світу в Анатолії все південне узбережжя Чорного моря перейшло під османське панування. Припинення правління династії Комнінів зміцнило претензію Фатіха бути «володарем двох морів і двох суходолів». Інші місця, приєднані тоді ж: Ґіресун, Різе.", "ca6ead13"]},
"OLAYLAR:1473-01-01:0":{"b": ["Остаточне завоювання Силіфке — злам останнього опору Караманідів", "d988bee4"], "d": ["Фортеця Силіфке одного разу, 1472 року, здалася Ґедіку Ахмеду-паші, але того ж року караманський Касим-бей за допомоги флоту хрестоносців у Середземному морі повернув собі фортецю. Після перемоги при Отлукбелі Фатіх доручив своєму синові та Ґедіку Ахмеду-паші остаточно захопити край; за допомоги колишніх османських гармашів підпалили пороховий склад, і фортеця швидко впала. Так було зламано останній опір Караманідів у горах Ташелі-Ічель; ліквідацію бейліку буде завершено 1474 року.", "e9814184"]},
"OLAYLAR:1473-08-11:0":{"b": ["Битва при Отлукбелі", "42c7194e"], "d": ["Правитель Ак-Коюнлу Узун-Хасан, який став великою силою на Сході та уклав союз із Венецією, зазнав при Отлукбелі тяжкої поразки від озброєного вогнепальною зброєю війська Фатіха. Перемога остаточно закріпила османську перевагу в Анатолії; вона стала також раннім доказом переваги централізованого війська з гарматами й рушницями над класичним військом. За статтею TDV про Ґюмюшхане, місто від 1467 року перебувало під владою Ак-Коюнлу; ця влада скінчилася з поразкою при Отлукбелі, і Ґюмюшхане остаточно перейшло під османське панування.", "63e0811f"]},
"OLAYLAR:1475-06-06:0":{"b": ["Крим переходить під османський протекторат", "44e3f7c8"], "d": ["Флот під командуванням Ґедіка Ахмеда-паші завоював міста південного узбережжя Криму, насамперед Кафу, яка перебувала в руках генуезців; це узбережжя стало безпосередньо османським санджаком. Кримське ханство ж за Менґлі Ґерая стало привілейованою залежною державою, яка визнавала османський сюзеренітет, і впродовж трьох століть було наріжним каменем північної політики; Чорне море фактично перетворилося на внутрішнє море османів. Інші місця, приєднані тоді ж: Бахчисарай, Керч, Азов.", "a3448d71"]},
"OLAYLAR:1481-05-03:0":{"b": ["Смерть Фатіха — справа султана Джема", "190ecf01"], "d": ["Після раптової смерті Фатіха дорогою в похід на престол зійшов Баязид II; його брат султан Джем, претендуючи на султанат, наказав у Бурсі читати хутбу та карбувати монету на своє ім'я. Зазнавши поразки, він шукав притулку спершу в мамлюків, а потім у родоських лицарів; Джем, який у руках лицарів і папства став козирем у торгах європейської дипломатії, помер 1495 року в Неаполі. Ця справа змушувала османську зовнішню політику п'ятнадцять років діяти обережно.", "7e488d7b"]},
"OLAYLAR:1514-08-23:0":{"b": ["Чалдиранська перемога", "fea64ebb"], "d": ["Прагнучи в корені усунути загрозу, створену сефевідською пропагандою в Анатолії, султан Селім Явуз (Грізний) на Чалдиранській рівнині завдяки перевазі в гарматах і рушницях завдав тяжкої поразки війську шаха Ісмаїла. Османи вступили в Тебриз; Східну й Південно-Східну Анатолію та лінію Мосул—Діярбакир було приєднано до османського управління. Підпорядкування курдських беїв османам завдяки зусиллям Ідріса Бітлісі створило рамки східного кордону, що зберігалися століттями.", "67b03a64"]},
"OLAYLAR:1516-08-24:0":{"b": ["Перемога при Мардж-Дабіку", "07d254d3"], "d": ["Мамлюцьке військо було розбите за кілька годин при Мардж-Дабіку на північ від Алеппо; старий султан Кансух аль-Гаурі помер під час битви. Завдяки перемозі, що навстіж відчинила брами Алеппо й Дамаска, Сирія, Ліван і Палестина перейшли під османське управління; відкрився шлях до Єгипетського походу, який мав покласти край Мамлюцькій державі.", "c4b15f39"]},
"OLAYLAR:1517-01-22:0":{"b": ["Ріданія — завоювання Єгипту і халіфат", "caf378d6"], "d": ["Османське військо, швидко подолавши Синайську пустелю, прорвало оборонну лінію Туман-бея при Ріданії та вступило в Каїр; Туман-бея, який продовжував опір, схопили й стратили, а Мамлюцька держава відійшла в історію. Єгипет, Хіджаз і священні міста перейшли під османське управління; аббасидського халіфа та священні реліквії перевезли до Стамбула. З переходом халіфату до Османської династії султани взяли на себе претензію на провід ісламського світу; контроль над Шляхом прянощів також приніс імперії великі доходи. Інші місця, приєднані тоді ж: Акка, Маан, Сайда, Карак.", "a0cc8fdc"]},
"OLAYLAR:1520-09-30:0":{"b": ["Султан Сулейман Кануні зійшов на престол", "f6512269"], "d": ["46-річне правління Сулеймана I, який після смерті Явуза зійшов на престол як його єдиний син чоловічої статі, вважають політичною, військовою, правовою та культурною вершиною імперії. Канун-наме, якими він систематизував звичаєве право, принесли йому титул «Кануні» (Законодавець); на Заході його називали «Пишним» (Magnificent). Символами цього періоду є твори архітектора Сінана, золота доба диванної літератури та перевага флоту в Середземному морі.", "cda7a2fb"]},
"OLAYLAR:1521-08-29:0":{"b": ["Завоювання Белграда", "59ef5cec"], "d": ["Белград, який Фатіх не зміг взяти 1456 року і який вважали «ключем до Центральної Європи», упав у першому поході Кануні внаслідок облоги біля злиття Дунаю та Сави. Південна лінія оборони Угорщини завалилася; це завоювання відчинило двері для центральноєвропейської кампанії, що через п'ять років привела до Мохача, а через двадцять — до анексії Буди.", "69dbb7cc"]},
"OLAYLAR:1522-12-21:0":{"b": ["Завоювання Родосу", "807bbb1e"], "d": ["Родос, база лицарів-йоаннітів, які загрожували морським шляхам Східного Середземномор'я та шляху паломництва, після багатомісячної кривавої облоги здався на умовах капітуляції; лицарям дозволили вільно залишити острів (згодом вони осіли на Мальті). Безпеку анатолійського узбережжя було забезпечено, а морський шлях Стамбул—Єгипет перейшов під безперервний османський контроль.", "aeedfb16"]},
"OLAYLAR:1526-08-29:0":{"b": ["Битва під Мохачем", "f3418b0d"], "d": ["Угорське військо було знищене на Мохацькій рівнині приблизно за дві години гарматним вогнем і перевагою в маневрі; король Лайош II під час утечі загинув у болоті. Мохач, одна з найшвидше виграних великих польових битв в османській історії, фактично поклав край незалежному Угорському королівству й відкрив у Центральній Європі добу османо-габсбурзького суперництва.", "48967894"]},
"OLAYLAR:1529-09-27:0":{"b": ["Перша облога Відня", "dc49ea4f"], "d": ["У поході, організованому проти зазіхань Габсбургів на угорський престол, османське військо взяло в облогу Відень; через те, що важкі гармати довелося залишити в дорозі, ранню зиму та труднощі з постачанням облогу зняли через три тижні. Хоча місто взяти не вдалося, османський вплив в Угорщині зберігся; підступи до Відня позначили межу логістичної досяжності імперії в Центральній Європі.", "a49fc760"]},
"OLAYLAR:1534-12-04:0":{"b": ["Завоювання Багдада — похід на два Іраки", "897092c3"], "d": ["У поході на «два Іраки» (арабський Ірак і перський Ірак) османи спершу вступили в Тебриз, а потім без бою — в Багдад; взяття давньої столиці Аббасидів принесло османському правителю великий авторитет в ісламському світі. Було відновлено гробницю імама-і Азама Абу Ханіфи; з приєднанням Багдада й Басри османські землі сягнули Перської затоки. Інші місця, приєднані тоді ж: Кіркук, Кербела.", "f3f80434"]},
"OLAYLAR:1538-09-28:0":{"b": ["Морська перемога під Превезою", "30dc0f97"], "d": ["Флот хрестоносців, створений під проводом папи, попри чисельну перевагу, був розбитий поблизу Превези завдяки тактиці Барбароси, який майстерно використав вітер і узбережжя; Андреа Дорія залишив поле бою. Перемога встановила в Середземному морі незаперечну османську морську перевагу, що тривала близько 33 років; у турецькій морській традиції це символічна дата Дня флоту. Інші місця, приєднані тоді ж: Аден, Бендери.", "0411d92f"]},
"OLAYLAR:1541-08-29:0":{"b": ["Анексія Буди — Угорщина стає османською провінцією", "db53b244"], "d": ["Кануні, вирушивши в похід через габсбурзьку облогу Буди, визволив місто, а потім узяв Центральну Угорщину під пряме османське управління, заснувавши Будинський бейлербейлік; Трансильванію ж зробили автономним князівством, залежним від османів. Такий тричастинний устрій Угорщини тривав близько 150 років і становив постійний кістяк османського управління в Центральній Європі.", "1eb63e33"]},
"OLAYLAR:1555-05-29:0":{"b": ["Амасійський мир", "a5afe0d1"], "d": ["Це перший офіційний мирний договір, що завершив багаторічні османо-сефевідські війни. Багдад та Ірак залишилися за османами, кордон у Східній Анатолії вперше був взаємно визнаний; Сефевіди зобов'язалися припинити шиїтську пропаганду в османських володіннях, а османи — гарантувати безпечний прохід іранським паломникам. Договір став першим зразком правових рамок відносин між двома державами.", "220b198f"]},
"OLAYLAR:1566-09-07:0":{"b": ["Сігетвар — смерть Кануні", "e2917ed2"], "d": ["72-річний Кануні помер у своєму шатрі за кілька годин до падіння фортеці Сігетвар, яку він обложив під час свого тринадцятого походу; Соколлу Мехмед-паша тижнями приховував смерть, щоб військо не розпалося. Фортецю взяли, але держава втратила свого найдовше правлячого й найблискучішого султана; на престол зійшов його син Селім II, і вага великих візирів в управлінні державою почала зростати.", "62c468a1"]},
"OLAYLAR:1571-08-01:0":{"b": ["Завоювання Кіпру", "e364a2b3"], "d": ["1570 року на Кіпрі, що перебував під венеційським управлінням, висадили десант; Нікосія впала швидко, а Фамагуста здалася лише після одинадцятимісячної облоги в серпні 1571 року. Острів, критично важливий для безпеки торговельних і паломницьких шляхів Східного Середземномор'я, організували як бейлербейлік і заселили людьми з Анатолії; це завоювання стало також приводом для великого союзу хрестоносців, що привів до Лепанто.", "6dcfdc0f"]},
"OLAYLAR:1571-10-07:0":{"b": ["Поразка під Лепанто", "6a1d44a9"], "d": ["Флот хрестоносців, об'єднаний після завоювання Кіпру, настиг османський флот у затоці Лепанто та знищив більшу його частину; капудан-паша (капудан-ї дер'я) Муезінзаде Алі-паша загинув як шахід, урятувалася лише ескадра Улуджа Алі. Після катастрофи великий візир Соколлу Мехмед-паша призначив Улуджа Алі-пашу капудан-пашею, доручивши йому зібрати розпорошений флот, і розпочав будівництво нового флоту на всіх верфях від Стамбула до Аланьї; проте абсолютна перевага в Середземному морі була психологічно підірвана.", "4cb5c93e"]},
"OLAYLAR:1596-10-26:0":{"b": ["Битва під Мезьокерестешем", "da308ec5"], "d": ["У найбільшій польовій битві Довгої війни (1593–1606) військо на чолі з самим Мехмедом III, опинившись на межі розпаду, згуртувалося завдяки умовлянням Ходжі Саадеддіна-ефенді й розгромило габсбурзьке військо. Її вважають останньою великою класичною польовою битвою, виграною османами; однак те, що вона не змінила загального перебігу війни, сприйняли також як ознаку зношеності військової системи.", "77f2a384"]},
"OLAYLAR:1606-11-11:0":{"b": ["Житваторокський мир", "39c01142"], "d": ["За договором, що завершив тринадцятирічну виснажливу війну, габсбурзького правителя вперше визнали рівним султанові з титулом «Римського імператора», а щорічну данину скасували. Територіальні втрати були майже нульові; проте ця зміна дипломатичної мови прочитується як символ кінця османської претензії на абсолютну перевагу над Європою.", "99a455e7"]},
"OLAYLAR:1639-05-17:0":{"b": ["Касрі-Ширінський договір", "c1acf3af"], "d": ["Договір, підписаний після того, як Мурад IV повернув Багдад (1638), поклав край османо-сефевідським війнам, що тривали понад сто років. Багдад та Ірак остаточно залишилися за османами, Реван було залишено Сефевідам; проведена лінія з незначними змінами стала основою нинішнього турецько-іранського кордону й вважається одним із найдовговічніших кордонів у світі. Договір залишив османам Бедре, Джессан, Менделі, Дертенг і Дерне; прикордонну фортецю Зенджір мали зруйнувати, села на захід від неї залишалися османам, а на схід — Ірану. Околиці фортеці Залім поблизу Шахрізора та Кизилджа-Кале залишилися за османами, Авроман і Міхрібан — за Іраном; фортеці Котур, Маку та Магазберд мали зруйнувати обидві сторони.", "c2d59f3f"]},
"OLAYLAR:1669-09-06:0":{"b": ["Завоювання Криту завершено", "e0d85604"], "d": ["Облога Кандії, остання дія Критської війни, що почалася 1645 року, завершилася завдяки рішучій трирічній операції Фазиля Ахмеда-паші; венеційський командувач Морозіні здав місто за договором. Боротьба, яка тривала близько чверті століття, увійшла в історію як найдовша облога в османській історії; остання велика латинська фортеця Східного Середземномор'я також перейшла під османське управління. Три невеликі скельні фортеці на північному узбережжі острова — Суда, Спіналонга та Грамвуса — ще залишалися за Венецією; оскільки вони збудовані на окремих острівцях, на карті їх неможливо показати окремо від решти Криту.", "314efa97"]},
"OLAYLAR:1672-10-18:0":{"b": ["Бучацький договір — найширші кордони", "b17b6e5a"], "d": ["За Бучацьким договором, підписаним після завоювання Кам'янця в польському поході, Поділля було приєднане до Османської держави, а частину України взято під протекторат. Так імперія досягла найширших своїх кордонів у Європі; цю точку вважають вершиною доби розширення й водночас її останньою ланкою.", "6d489670"]},
"OLAYLAR:1683-09-12:0":{"b": ["Розгром під час другої облоги Відня", "7d889252"], "d": ["Двомісячна облога Відня Мерзіфонлу Карою Мустафою-пашею обернулася розгромом через раптовий удар, якого завдав із висот Каленберґа польський король Ян Собеський; військо відступило, покинувши обози, а Мерзіфонлу стратили в Белграді. Війна зі Священною лігою, створеною після цієї перемоги, тривала 16 років; цей розгром називають моментом початку великого занепаду в османській історії.", "88ceb19f"]},
"OLAYLAR:1692-01-01:0":{"b": ["Завоювання фортеці Грамвуса — однієї зі скельних фортець Криту, що залишалися за Венецією", "3ddf9eeb"], "d": ["Хоча зі здачею Кандії 1669 року завоювання Криту вважали здебільшого завершеним, скельна острівна фортеця Грамвуса на північно-західному краю острова ще двадцять три роки залишалася в руках Венеції. Зі взяттям її 1692 року було ліквідовано один із трьох венеційських залишків на Криті; Суда та Спіналонга чекатимуть Морейського походу 1715 року.", "05e94fe9"]},
"OLAYLAR:1699-01-26:0":{"b": ["Карловицький мир — перша велика територіальна втрата", "8f7e2546"], "d": ["За Карловицьким миром, що завершив шістнадцятирічні війни Священної ліги, Угорщина й Трансильванія відійшли Австрії, Поділля — Польщі, Морея та далматинське узбережжя — Венеції. Уперше в османській історії землі такого масштабу втрачалися за столом переговорів і назавжди; договір вважають вихідним документом нової доби, коли імперія перейшла до оборони перед Європою, і він є також переломним моментом в історії османської дипломатії. Поселення, що того ж дня змінили власника в атласі: Костайниця та Ясеновац (від османів до Габсбургів; текст договору залишає Castanoviz у руках імператора, дня передання Ясеноваца в джерелі немає, записано день договору) та Превеза (від Венеції до османів; TDV karlofca: згідно з положенням, підписаним 24 раджаба 1110 / 26 січня 1699 року, венеційські окуповані місця на північ від затоки Лепанто було повернено). Крім того, атлас записує Костайницю та Ясеновац на габсбурзький бік, Умань і Вінницю на Правобережній Україні — від османів до Польщі (TDV merzifonlu-kara-mustafa-pasa; IEU Vinnytsia: турецька влада 1672-99), а Надін у Далмації — Венеції (дня передання саме цього поселення в джерелі немає, записано день договору; межі періоду Надіна не перевірені за джерелом — задекларована приблизність). Вониця на північ від затоки Лепанто також повертається від Венеції османам (TDV karlofca); у Далмації Врана (Урана) серед місць, що залишаються за Венецією (межу періоду не перевірено — задекларовано).", "0909e24e"]},
"OLAYLAR:1711-07-19:0":{"b": ["Прутська перемога", "2583572f"], "d": ["У війні, що спалахнула через справу шведського короля, який після поразки під Полтавою знайшов притулок в османів, військо царя Петра I було оточене на березі Пруту й змушене здатися. За підписаним договором було повернуто Азов; рішення ж не знищувати військо й відпустити царя увійшло в історію як таке, про яке сперечаються й донині.", "ce9c2996"]},
"OLAYLAR:1715-01-01:0":{"b": ["Завоювання фортець Суда та Спіналонга — стирання останнього венеційського сліду на Криті", "7261f7ba"], "d": ["Через двадцять три роки після падіння Грамвуси 1692 року в межах одного з відгалужень Морейського походу завоювали також фортеці Суда та Спіналонга — два останні опорні пункти Венеції на Криті. Так завоювання Криту, розпочате 1645 року, через сорок шість років було завершене до останнього клаптика острова.", "d2044cae"]},
"OLAYLAR:1730-09-25:0":{"b": ["Повстання Патрони Халіля", "100941a4"], "d": ["Невдачі на іранському фронті, податки та гнів на розкіш палацового оточення переросли у велике повстання під проводом лазневого банщика Патрони Халіля. Великого візира Ібрагіма-пашу вбили, Ахмеда III скинули з престолу, і Доба тюльпанів скінчилася; те, що повстанці місяцями панували в місті, разюче показало крихкість центральної влади.", "d87eea77"]},
"OLAYLAR:1739-09-18:0":{"b": ["Белградський мир — повернення Белграда, Смедерева та північної Сербії", "ba7f8e46"], "d": ["Наприкінці війни (1736–1739), яку вели на два фронти проти Австрії та Росії, було повернуто Белград і Північну Сербію; Росія погодилася демілітаризувати Азов і не тримати флоту на Чорному морі. Договір, який вважають останнім великим успіхом османської дипломатії та війська XVIII століття, подарував імперії чверть століття миру. Інші поселення, що того ж дня в атласі повертаються від Австрії османам: Хісарджик (Ґроцка) (ланцюг головного центру Белграда; TDV belgrad), Крайова, Римніку-Вилча та Турну-Северін (повернення Малої Волощини османам, у волоський васалітет). Босанський Брод і Босанська Дубиця в смузі вздовж Сави в атласі повертаються османам 28 вересня 1739 року (TDV bosna-hersek; TDV mahmud-i--osmanli: 28 вересня 1739). Тиргу-Жіу в Малій Волощині також того ж дня повертається османам.", "118d49db"]},
"OLAYLAR:1770-07-06:0":{"b": ["Чесменський погром", "840b30bd"], "d": ["Російський флот, що за британської підтримки вийшов у Середземне море, напав брандерами на османський флот у Чесменській гавані, де той укрився, і спалив його майже вщент. Росія вперше постала в Середземному морі як велика морська сила; ця катастрофа стала одним з ударів, що визначили долю війни, яка привела до Кючук-Кайнарджі 1774 року, і виявила потребу докорінної реформи флоту.", "5b133a56"]},
"OLAYLAR:1774-07-21:0":{"b": ["Кючук-Кайнарджійський мир", "2776dcdb"], "d": ["За Кючук-Кайнарджійським миром, що завершив війну 1768–1774 років і вважається одним із найтяжчих договорів в османській історії, Кримському ханству надали «незалежність» — фактично створивши сферу російського впливу. Росія утвердилася на чорноморському узбережжі, здобула для торгових суден право проходу через Протоки та постійне посольство в Стамбулі; туманне положення про протекцію над православними підданими прочинило двері приводам для втручання в наступному столітті. Уперше з-під османської влади виводили землю з мусульманським населенням.", "b677ebfc"]},
"OLAYLAR:1783-04-19:0":{"b": ["Анексія Криму Росією", "bdf6faa8"]},
"OLAYLAR:1789-04-07:0":{"b": ["Селім III і Нізам-і Джедід", "d53aec21"], "d": ["Селім III, який зійшов на престол у розпал війни, зрозумівши, що поразки мають структурний характер, започаткував під назвою «Нізам-і Джедід» (Новий порядок) широку програму реформ: нове військо, вишколене за європейським зразком, окрему скарбницю для його фінансування (Ірад-і Джедід), зміцнення інженерних шкіл і перші постійні посольства в європейських столицях. Цю програму вважають початком модерної турецької реформаторської традиції; однак через опір військових корпусів та аянів 1807 року вона була повалена.", "87394990"]},
"OLAYLAR:1798-06-12:0":{"b": ["Ліквідація мальтійських лицарів — зупинка французького флоту дорогою", "d62f901d"], "d": ["Французький флот, що плив до Єгипту, дорогою зайшов на Мальту; лицарі святого Іоанна (мальтійські) здали острів без особливого опору. Так перестав існувати останній оплот лицарського ордену, вигнаного 1522 року з Родосу й осілого тут. Через два роки Мальта опиниться в руках британців, а Наполеон з острова вирушив просто до Александрії.", "aac1fe49"]},
"OLAYLAR:1798-07-01:0":{"b": ["Наполеонівське вторгнення до Єгипту", "93fede5f"], "d": ["Армія генерала Бонапарта висадилася в Александрії й окупувала Єгипет; цей похід, спрямований проти британського шляху до Індії, став першим прямим нападом європейської держави на центральні землі османів. Напад Нельсона під Абукіром та оборона Акки Джеззаром Ахмедом-пашею зламали французький наступ; окупація скінчилася 1801 року, але у вакуумі, який вона залишила, почалися піднесення Мехмеда Алі-паші з Кавали та доба «Східного питання».", "b1ca7226"]},
"OLAYLAR:1808-10-07:0":{"b": ["Сенед-і Іттіфак (Союзна грамота)", "cce49ef5"], "d": ["Документ, підписаний між палацом і могутніми провінційними родинами аянів за ініціативою Алемдара Мустафи-паші, аяна Рущука, який посадив на престол Махмуда II; аяни зобов'язувалися бути вірними султанові та надавати військову підтримку, а держава визнавала їхнє існування та права. Оскільки це був перший в османській історії приклад обмеження влади султана документом, деякі історики вважають його далеким початком конституційної традиції; фактично за кілька місяців він втратив чинність.", "2d97fdfe"]},
"OLAYLAR:1821-03-06:0":{"b": ["Почалося Грецьке повстання", "a7293715"], "d": ["Повстання, підготоване організацією «Філікі Етерія», спалахнуло спершу у Волощині, а потім головними силами — в Мореї; держава, зайнята клопотом з Алі-пашею Тепеленським, із першою реакцією запізнилася. Завдяки палким симпатіям до греків у європейській громадській думці (філеллінізму) повстання швидко перетворилося на міжнародну справу; так було запалено ґніт першого на османських землях успішного руху за незалежність доби націоналізму. Інші поселення, втрачені тоді ж: Афіни, Патри (Бальябадра), Фіви, Лівадія, Елевсін (Аттика), Месолонгіон.", "f11097ac"]},
"OLAYLAR:1821-04-02:0":{"b": ["Перше збройне повстання в Мореї", "77e6250f"], "d": ["Після переправи через Прут повстання перекинулося на Морею: за збройним виступом, що почався в Калавриті (21 березня за юліанським календарем), відбулися рухи в Патрах, Каламаті та Мані; Морея швидко перетворилася на осередок загального повстання, і османська адміністрація втратила більшу частину півострова. Інші поселення, втрачені тоді ж: Афіни, Патри (Бальябадра), Фіви, Лівадія, Елевсін (Аттика), Месолонгіон.", "143953b8"]},
"OLAYLAR:1826-06-15:0":{"b": ["Вак'а-і Хайрійє — скасування яничарського корпусу", "08c9372a"], "d": ["Яничарів, які перекинули казани на знак бунту проти вишколу новоствореного корпусу ешкінджі, було знищено гарматним вогнем заздалегідь підготованих Махмудом II вірних частин у їхніх казармах на Етмейдани; корпус скасували разом з усіма його підрозділами та пов'язаними з ним бекташійськими текіє. Ця операція, що увійшла в історію під назвою, яка означає «Щаслива подія», ліквідувавши чотиристолітню установу, відкрила шлях війську Асакір-і Мансуре-і Мухаммедійє та всім подальшим централізаторським реформам.", "9ee152dd"]},
"OLAYLAR:1827-10-20:0":{"b": ["Наваринський погром", "ee579e7f"], "d": ["Османо-єгипетський флот, який придушував грецьке повстання, спалила в Наварині об'єднана англо-франко-російська ескадра, що увійшла в гавань без оголошення війни; було втрачено майже шістдесят кораблів і тисячі моряків. Цей напад, який європейська дипломатія відмахнула як «прикрий інцидент», фактично гарантував незалежність Греції та відкрив шлях до османо-російської війни 1828–29 років.", "0d4b2c6f"]},
"OLAYLAR:1839-11-03:0":{"b": ["Ферман Танзімату", "5042ce7b"], "d": ["Хатт-і Хумаюном, зачитаним у Ґюльхане, держава взяла під гарантію безпеку життя, майна й честі всіх підданих незалежно від віри; було проголошено принципи справедливості в оподаткуванні, ладу у військовій службі та неможливості покарання без суду. Ферман, витвір Мустафи Решида-паші, вважають першим великим документом османської модернізації конституційного характеру, і він дав назву добі реформ — «Танзімат» (1839–1876); у цих рамках проводилася докорінна перебудова управління, права, освіти та фінансів.", "6ace4b82"]},
"OLAYLAR:1853-10-04:0":{"b": ["Почалася Кримська війна", "3b9ca3c8"], "d": ["Криза, що почалася з питання про святі місця та претензії Росії на протекцію над православними підданими, з оголошенням війни османами перейшла у відкритий конфлікт; після Синопського погрому на боці османів у війну вступили Британія та Франція (пізніше П'ємонт). Після висадки союзних армій у Криму та взяття Севастополя війну було виграно Паризьким договором 1856 року; проте перша зовнішня позика, взята в роки війни (1854), втягнула імперію в спіраль фінансової залежності, що тривала пів століття.", "bae16135"]},
"OLAYLAR:1856-02-18:0":{"b": ["Ферман про реформи (Іслахат Фермани)", "78ff234d"], "d": ["Ферман, проголошений перед Паризькими мирними переговорами, розширив принципи Танзімату й надав немусульманським підданим широкі права рівності, зокрема на державну службу, військову службу та відкриття шкіл; було перебудовано організацію релігійних громад. За Паризьким договором, підписаним згодом, Османську державу офіційно прийняли до сім'ї європейського міжнародного права, а її територіальну цілісність поставили під спільну гарантію великих держав — гарантію, яка на практиці стане новими дверима для втручань.", "cfe6d847"]},
"OLAYLAR:1876-12-23:0":{"b": ["Канун-і Есасі — Перша конституційна доба", "0fe052c1"], "d": ["У день відкриття міжнародної конференції, що зібралася в Стамбулі для обговорення Балканської кризи, під гарматний салют проголосили першу османську конституцію; Канун-і Есасі, витвір руху «Нових османів» на чолі з Мідхатом-пашею, запроваджував двопалатний парламент. Меджліс-і Мебусан відкрився в березні 1877 року; однак Абдул-Гамід II, посилаючись на Війну 93-го року, у лютому 1878 року на невизначений строк припинив засідання парламенту, і конституція тридцять років залишалася призупиненою.", "c0f01a41"]},
"OLAYLAR:1877-04-24:0":{"b": ["Війна 93-го року (османо-російська війна 1877–78)", "5bd96af7"], "d": ["У війні, яку називають «Війною 93-го року», оскільки вона припала на 1293 рік за румійським календарем, російські армії наступали на двох фронтах; хоч оборона Плевни Ґазі Османом-пашею та кавказькі битви Ахмеда Мухтара-паші стали легендами, фронт обвалився, і росіяни дійшли аж до Єшількьоя (Сан-Стефано). Війна спричинила великі хвилі переселення мусульман із Балкан і Кавказу в напрямку Стамбула, наслідки яких відчутні донині; демографічна та фінансова структура імперії вже ніколи не змогла повернутися до попереднього стану.", "3a2b2296"]},
"OLAYLAR:1878-07-13:0":{"b": ["Берлінський трактат", "47f76a49"], "d": ["Берлінський конгрес, який в ім'я рівноваги великих держав переглянув створену в Сан-Стефано «Велику Болгарію», все ж залишив тяжку картину: Сербія, Чорногорія та Румунія стали незалежними; було створено автономне Болгарське князівство; Боснію і Герцеговину віддали під австрійську окупацію, Кіпр — під британське управління, а Карс, Ардаган і Батум — Росії. П'ятсотлітній османський лад у Румелії значною мірою розпався; «східне питання» стало постійним пунктом порядку денного європейської дипломатії. Інші поселення, втрачені тоді ж: Пловдив, Відін, Тирново, Варна, Шумен, Силістра, Русе, Бухарест, Ясси, Констанца. Румунія в обмін на передання Бессарабії Росії отримала Тулчу та Добруджу: Тулча, Бабадаг, Мечин, Ісакча, Хиршова та Мангалія в Північній Добруджі перейшли до Румунії.", "5c7d5594"]},
"OLAYLAR:1881-05-12:0":{"b": ["Окупація Тунісу та Управління Османського державного боргу", "c7e25598"], "d": ["Скориставшись як приводом інцидентами на алжирському кордоні, Франція окупувала Туніс і за договором у Бардо взяла його під свій протекторат; османська присутність у Північній Африці звелася до Триполітанії. Виданим того ж року Мухарремським декретом для управління зовнішніми боргами, що збанкрутували, було створено Управління Османського державного боргу (Дююн-і Умумійє), в якому були представлені кредитори: основні доходи, як-от сіль, тютюн і шовк, були прямо підпорядковані цій іноземній адміністрації, а фінансовий суверенітет тяжко обмежено. Інші поселення, втрачені тоді ж: Кайруан, Габес, Сфакс, Джерба.", "64f23b86"]},
"OLAYLAR:1882-09-13:0":{"b": ["Британська окупація Єгипту", "f1269768"], "d": ["Рух Урабі-паші, що піднявся в Єгипті проти фінансового банкрутства та іноземного контролю, британська армія, яка висадилася після бомбардування Александрії, розгромила в переможній битві при Тель-ель-Кебірі, і Каїр було окуповано. Хоча юридично Єгипет і далі залишався пов'язаним з Османською державою, фактично він перейшов під британське управління; контроль над Суецьким каналом став осердям британської імперської стратегії.", "b7bcf2d2"]},
"OLAYLAR:1908-07-23:0":{"b": ["Проголошення Другої конституційної доби", "95ee2fd2"], "d": ["Перед рухом, що розрісся після того, як офіцери, пов'язані з комітетом «Єднання і поступ», пішли в гори в Македонії, Абдул-Гамід II відновив дію Канун-і Есасі; «проголошення свободи» зустріли з захватом, і було проведено вибори. Однак стабільність не настала: після придушення подій 31 березня (квітень 1909) Абдул-Гаміда скинули з престолу; у ці ж бурхливі місяці сталися проголошення незалежності Болгарії, анексія Боснії та поворот Криту до Греції.", "370f359f"]},
"OLAYLAR:1911-09-29:0":{"b": ["Триполітанська війна", "ed441994"], "d": ["Італія, шукаючи колоній, оголосила війну Триполітанії, останній османській землі в Північній Африці, і окупувала узбережжя; оскільки держава без флоту не могла надіслати регулярні війська, молоді офіцери, як-от Мустафа Кемаль та Енвер-бей, таємно пробралися в цей край і разом із сенуситськими племенами організували дієвий опір. За Ушійським договором, підписаним після вибуху Балканської війни (18 жовтня 1912), Лівію віддали Італії; крім того, Італія окупувала Родос і Додеканес.", "9820482a"]},
"OLAYLAR:1913-05-30:0":{"b": ["Лондонський договір — втрата Румелії", "f3f976df"], "d": ["За Лондонським договором, що завершив Першу балканську війну, було втрачено всі землі на захід від лінії Мідьє—Енез та егейські острови; Албанія стала незалежною. Від Румелії, яка понад п'ятсот років була демографічним, економічним і культурним центром ваги імперії, залишалася тільки Східна Фракія (Едірне повернули у Другій балканській війні); ця втрата докорінно посилила жорсткість воєнної та переселенської політики уряду йоніністів. Було втрачено такі місця на захід від лінії Мідьє—Енез: Скоп'є, Велес, Штип, Струмиця, Дойран, Гевгелія, Бітола, Охрид, Дебар (Дібра), Призрен, Приштина, Печ (Пея), Нові-Пазар, Косово Поле; Серрес, Драма, Кавала, Петрич, Неврокоп, Ксанті, Комотіні, Дедеагач, Дідімотіхо, Чірмен, Ферес, Софлі, Орестіада (Кумчіфтлігі), Правіште (Елефтеруполіс), Стерна, Таврі, Умур-Факіх (Факія), Малак-Дервент (Лалково); на Криті — Ханья, Кандія, Ретимно, Сітія та Сфакія.", "b193bdae"]},
"OLAYLAR:1914-11-01:0":{"b": ["Вступ у Першу світову війну", "05a0252e"], "d": ["Те, що лінійні кораблі «Ґебен» і «Бреслау», які втекли від британців, впустили через Протоки, видавши їх за куплені, крок за кроком втягувало державу на бік Німеччини; після того як флот під командуванням адмірала Сушона обстріляв російські порти (29 жовтня), війна фактично почалася, а взаємні оголошення надійшли на початку листопада. Попри проголошення Великого джихаду (Джихад-і Екбер), очікуваного ефекту не виникло; чотири роки імперія вела боротьбу за існування на п'яти окремих фронтах — від Кавказу до Палестини.", "a9f179e7"]},
"OLAYLAR:1915-03-18:0":{"b": ["Перемога під Чанаккале", "95d888e8"], "d": ["Армаду союзників, що мала на меті захопити Стамбул і дістатися до Росії, 18 березня відкинули від Проток вогонь мінних загороджень і фортів; лінія мін, поставлена мінним загороджувачем «Нусрет», визначила долю битви. Сухопутну Галліпольську операцію, що почалася в квітні, також зупинили під Анафарталаром і на Чонк-Баїрі; у січні 1916 року союзники повністю евакуювали півострів. На цьому фронті пролунало ім'я підполковника Мустафи Кемаля; перемогу, здобуту ціною близько чверті мільйона загиблих за віру та інших втрат, вважають місцем, де народилися кадри й дух Національної боротьби.", "005303c3"]},
"OLAYLAR:1916-06-10:0":{"b": ["Повстання шарифа Хусейна", "75f7c58c"], "d": ["Мекканський емір шариф Хусейн після таємного листування з британцями повстав під обіцянку незалежного арабського королівства; Хіджазька залізниця стала мішенню нападів. Хоч легендарна оборона Медини Фахреддіном-пашею, що тривала навіть після перемир'я, залишилася символом опору, повстання, поєднавшись із британським наступом на Палестинському фронті, прискорило розпад османського панування в арабських вілаєтах. Інші поселення, втрачені тоді ж: Хурма, Тураба.", "f7c6b3e9"]},
"OLAYLAR:1918-10-30:0":{"b": ["Мудроське перемир'я", "9e87c767"], "d": ["Османська держава, фронти якої через крах Болгарії виявилися відірваними один від одного, вийшла з війни за перемир'ям, підписаним на борту лінкора «Агамемнон». Відкриття Проток і особливо 7-ма стаття, яка давала змогу окупувати місця, де є загроза безпеці, незабаром стали юридичним прикриттям фактичного поділу: було окуповано Мосул, Александретту, а потім Ізмір і Стамбул. Перемир'я вважають документом фактичного кінця імперії. Інші поселення, втрачені тоді ж: Хама, Дамаск, Хомс.", "261b57f2"]},
"OLAYLAR:1919-05-19:0":{"b": ["Мустафа Кемаль у Самсуні — Національна боротьба", "09a8f784"], "d": ["В атмосфері обурення, спричиненого окупацією Ізміра, Мустафа Кемаль-паша, який висадився в Самсуні на посаді інспектора 9-ї армії, обернув свої офіційні обов'язки на організацію опору в Анатолії. Амасійський циркуляр та Ерзурумський і Сіваський конгреси стали продовженням цього виступу; принцип «незалежність нації врятують лише рішучість і воля самої нації» став ядром політичної програми Національної боротьби.", "330e4c51"]},
"OLAYLAR:1920-04-23:0":{"b": ["Відкриття Великих національних зборів Туреччини та Севр", "2008feec"], "d": ["Після офіційної окупації Стамбула та розгону Меджлісу-і Мебусан 23 квітня 1920 року в Анкарі відкрилися Великі національні збори; зібрання, яке зосередило в собі надзвичайні повноваження, стало ядром нової держави, що спиралася на національну волю. Севрський договір, підписаний у серпні стамбульським урядом, ділив Анатолію; Великі національні збори оголосили тих, хто підписав договір, зрадниками батьківщини, і Севр так і не був втілений.", "9b4f7c0b"]},
"OLAYLAR:1921-09-13:0":{"b": ["Битва на Сакарії", "f2f970a6"], "d": ["Грецький наступ, що наблизився до Анкари на 50 кілометрів, було зламано в битві, яка тривала 22 дні й 22 ночі й велася за наказом Мустафи Кемаля-паші, що перебрав повноваження головнокомандувача: «Немає лінії оборони, є поверхня оборони». Грецька армія вперше перейшла до стратегічної оборони; перемога принесла Мустафі Кемалю звання гази та чин маршала (мюшира) й відчинила двері Анкарській угоді з Францією та міжнародному визнанню.", "f3372310"]},
"OLAYLAR:1922-09-09:0":{"b": ["Великий наступ і визволення Ізміра", "172a50c4"], "d": ["Наступ, розпочатий уранці 26 серпня з Коджатепе, 30 серпня під Думлупинаром у Битві головнокомандувача привів до знищення головних грецьких сил; під час переслідування, що тривало за наказом «Арміє, твоя перша мета — Середземне море, вперед!», 9 вересня визволили Ізмір. За Муданійським перемир'ям (11 жовтня) Східну Фракію повернули без бою; військова перемога визначила силу за столом переговорів нової держави, яку мали утворити в Лозанні.", "02bd94a5"]},
"OLAYLAR:1922-11-01:0":{"b": ["Скасування султанату", "9f36a9f6"], "d": ["Коли на Лозаннські переговори запросили й стамбульський уряд, Великі національні збори 1 листопада 1922 року відокремили султанат від халіфату й скасували султанат; 623-річне правління Османської династії юридично скінчилося. Мехмед VI Вахідеддін 17 листопада залишив країну на борту британського лінкора; на посаду халіфа за рішенням Великих національних зборів поставили Абдул-Меджида-ефенді, а цю посаду також буде скасовано 3 березня 1924 року.", "910b763d"]},
"OLAYLAR:1923-07-24:0":{"b": ["Лозаннський договір", "38c27f7d"], "d": ["За Лозаннським мирним договором, підписаним після восьми місяців важких переговорів, кордони, повна незалежність і суверенітет нової турецької держави дістали міжнародне визнання; капітуляції було скасовано, Управління Османського державного боргу введено в процес ліквідації, врегульовано обмін населенням. Лозанну, яка фактично зробила Севр нікчемним, вважають дипломатичною перемогою Національної боротьби та засадничим зовнішнім документом Республіки.", "6d498c3f"]},
"OLAYLAR:1923-10-29:0":{"b": ["Проголошення Республіки", "d5bfcdfb"], "d": ["Республіку було проголошено, коли Великі національні збори конституційною поправкою ухвалили положення: «Форма правління Турецької держави — республіка»; Мустафу Кемаля-пашу обрали першим президентом. Так завершилася 624-річна османська епопея, що почалася 1299 року як прикордонний бейлік, а на спадщині імперії постала нова держава, у якій суверенітет безумовно належить нації.", "f5cabb8c"]},
"OLAYLAR_EK4:1803-05-01:0":{"b": ["Албанські солдати скинули намісника Єгипту", "c76a0ec2"], "d": ["Албанські частини, яким не виплатили платню (улюфе), збунтувалися й змусили намісника Хюсрев-пашу тікати з цитаделі. У вакуумі, що виник після відходу французів, мамлюцькі беї, албанський корпус і намісники, призначені Високою Портою, вступили в тристоронню боротьбу; Мехмед Алі висунувся наперед, вибудовуючи рівновагу в цьому трикутнику. Інші поселення, втрачені того самого дня: Таїф.", "669d61a0"]},
"OLAYLAR_EK4:1805-05:0":{"b": ["Улеми Каїра проголосили Мехмеда Алі намісником", "a16752f2"], "d": ["Каїрські ремісники та улеми, виснажені податковим тягарем, повстали під проводом накіб аль-ашрафа Омара Макрама, заявили, що не визнають намісника Хуршид-пашу, і посадили на намісницьке місце Мехмеда Алі. Обрання намісника народом — рідкісна подія в османській історії.", "1572b66f"]},
"OLAYLAR_EK4:1805-07-03:0":{"b": ["Висока Порта визнала доконаний факт: фірман про намісництво в Єгипті", "b86736a3"], "d": ["Висока Порта, не маючи сил утримати в Єгипті власного кандидата, надіслала Мехмедові Алі фірман про намісництво в Єгипті з рангом візира. На карті від цієї дати Єгипет переходить у васальний (світлий тон) шар: юридично це османська земля, фактично — володіння династії Кавалали. Інші поселення, що того самого дня переходять у васальний шар: Каїр, Александрія, Думьят, Асьют, Асуан, Ібрім, Суец, Решід (Розетта).", "e769c607"]},
"OLAYLAR_EK4:1807-03-17:0":{"b": ["Британська експедиція Фрейзера висадилася в Александрії", "4d6c31be"], "d": ["У відповідь на зближення Османської держави з Францією Британія відправила до Єгипту десантний корпус. Мехмед Алі тоді воював із мамлюками у Верхньому Єгипті; він швидко повернувся й організував оборону.", "fd5f278f"]},
"OLAYLAR_EK4:1807-04-21:0":{"b": ["Розгром під Решідом (Розеттою) — британців відбито", "3636004c"], "d": ["Британська колона, що увійшла в містечко Решід, зазнала тяжких втрат у вуличних боях; у вересні війська повністю залишили Єгипет. Ця перемога зміцнила авторитет Мехмеда Алі як у Єгипті, так і в Стамбулі.", "68a2ba26"]},
"OLAYLAR_EK4:1811-03-01:0":{"b": ["Різанина в цитаделі: знищення мамлюцьких беїв", "84030b97"], "d": ["Мамлюцьких беїв, запрошених на урочисту процесію з нагоди хіджазького походу, заманили в пастку у вузькому проході Каїрської цитаделі й знищили. Так скінчився п'ятивіковий вплив мамлюків, і в Єгипті в Мехмеда Алі не залишилося суперників.", "1ca00e33"]},
"OLAYLAR_EK4:1811-09-03:0":{"b": ["Почався хіджазький похід — військо вирушило на Янбу морем із Суеца та суходолом паломницьким шляхом", "1c05c159"], "d": ["Повернення Харамейну, що з 1803 року перебував під саудівсько-ваххабітською владою, було для Махмуда II найбільшим питанням легітимності; оскільки сил Високої Порти не вистачало, завдання доручили намісникові Єгипту. Мехмед Алі послав на чолі війська свого шістнадцятирічного сина Тосуна.", "5e614d69"]},
"OLAYLAR_EK4:1811-10-01:0":{"b": ["Янбу здався — перша прибережна база хіджазького походу", "179bc78d"], "d": ["Близько двох тисяч албанських піхотинців, що вирушили із Суеца на новозбудованих кораблях, у жовтні 1811 року висадилися поблизу Янбу; містечко здалося після дводенного слабкого опору. Кіннота під командуванням Тосуна йшла паломницьким шляхом суходолом і дісталася Янбу через Акабу та Ель-Ваджх лише через два тижні. Янбу став першою базою в Хіджазі для єгипетського війська, яке мало йти на Медину та Мекку.", "cfc2ed8a"]},
"OLAYLAR_EK4:1812-01-01:0":{"b": ["Перша поразка в ущелині Сафра — Джадіда", "99ef804d"], "d": ["Єгипетський авангард, що потрапив у засідку у вузьких гірських проходах, розсіявся. Ця поразка стала тактичним уроком походу: з'ясувалося, що без підтримки бедуїнських племен просуватися Хіджазом неможливо.", "765dd19d"]},
"OLAYLAR_EK4:1812-12-03:0":{"b": ["Медину повернено", "6f6a5d55"], "d": ["Після тривалої облоги Медина здалася. Повернення міста Пророка відсвяткували в Стамбулі гарматними салютами; як нагороду Мехмедові Алі надали ще й намісництво в Джидді.", "45cc4c79"]},
"OLAYLAR_EK4:1813-01-23:0":{"b": ["Мекку повернено — паломницький шлях відкрито", "3d6d66a0"], "d": ["Єгипетські війська, що увійшли до Мекки, наказали знову читати біля Кааби хутбу від імені османського султана. Паломницькі каравани, перервані на десять років, змогли вирушити знову. На карті Хіджаз повертається під османську владу, але, оскільки ним керують із Каїра, його позначено васальним тоном. Інше місце, що перейшло під васальне управління того самого дня: Джидда.", "f0970e28"]},
"OLAYLAR_EK4:1813-05-02:0":{"b": ["Повернення Таїфа — завершення хіджазького походу", "6315fb31"], "d": ["Після Медини (грудень 1812 р.) та Мекки (січень 1813 р.) єгипетське військо під командуванням Тосун-паші насамкінець відвоювало у ваххабітів Таїф. Десятирічне панування Саудів скінчилося, і всі три священні центри Хіджазу знову опинилися під османсько-єгипетським контролем.", "374bf563"]},
"OLAYLAR_EK4:1813-08-28:0":{"b": ["Мехмед Алі особисто перебрався до Хіджазу", "fda0ea2d"], "d": ["Побачивши, що похід ведеться мляво, намісник узяв керівництво безпосередньо у свої руки; торгуючись із вождями племен, він намагався розкласти саудівський фронт зсередини. Частка Єгипту в червономорській торгівлі також зросла завдяки цьому походу.", "aeb051d1"]},
"OLAYLAR_EK4:1815-01-20:0":{"b": ["Битва при Бісалі: саудівські війська розгромлено", "9c9ab91f"], "d": ["Саудити, зазнавши тяжкої поразки в польовій битві, відступили у внутрішні райони. Укладене перемир'я виявилося нетривким; через два роки операцію перенесуть у серце Неджду. Після цієї перемоги атлас вважає, що Тураба та Хурма на схід від Таїфа вийшли з-під саудівської влади (джерело про подію — Lorimer, Gazetteer; свідчення щодо самих поселень і день 13 січня є задекларованим наближенням).", "551e1880"]},
"OLAYLAR_EK4:1816-09-01:0":{"b": ["Ібрагім-паша вирушив у недждський похід", "d5ed80d1"], "d": ["Ібрагім-паша, який перейняв командування після смерті брата Тосуна, розпочав важкий дворічний марш пустелею. Військо, просуваючись від колодязя до колодязя й усуваючи племена одне за одним, підступило до саудівської столиці.", "e84c2cef"]},
"OLAYLAR_EK4:1818-09-09:0":{"b": ["Дірія впала — кінець Першої Саудівської держави", "aa96206d"], "d": ["Після шестимісячної облоги Дірія здалася й була зруйнована. Еміра Абдаллаха ібн Сауда відправили до Стамбула та стратили. Османський прапор уперше сягнув так глибоко у внутрішню Аравію; гарнізон у Неджді залишався до 1824 року. Інші місця, приєднані того самого дня: Дірія (Неджд).", "4b161cf5"]},
"OLAYLAR_EK4:1820-07-20:0":{"b": ["Почався суданський похід", "b1fc6905"], "d": ["Мета Мехмеда Алі була потрійною: набрати солдатів до свого війська, дістатися сеннарського золота та знищити залишки мамлюків, що втекли. Військо під командуванням його сина Ісмаїл-паші рушило на південь уздовж Нілу.", "478563e9"]},
"OLAYLAR_EK4:1820-11-01:0":{"b": ["Донгола без насильства переходить до єгипетського війська (мамлюки залишили її в червні 1820 р.)", "bc5942c0"], "d": ["Донгола на великому вигині Нілу після того, як у червні 1820 року її залишили мамлюки, без насильства перейшла до рук єгипетського війська Ісмаїл-паші. На карті від цієї дати Судан з'являється у васальному шарі: завойовником є Каїр, і правитиме також Каїр.", "61ac03d6"]},
"OLAYLAR_EK4:1820-12-04:0":{"b": ["Битва при Джебель ад-Дайка — конфедерація Шайкія зазнає вирішальної поразки від єгипетського війська", "befc9539"], "d": ["Військо Ісмаїл-паші, сина Мухаммеда Алі-паші, через місяць після першої сутички при Курті здолало шайкія в другій, вирішальній битві поблизу Джебель ад-Дайки. Вождь шайкія Макк Субайр здався; Макк Шавіш продовжував опір. Відтоді єгипетська влада над вигином Нілу стала сталою.", "5e0734a7"]},
"OLAYLAR_EK4:1821-06-14:0":{"b": ["Султанат Сеннар (Фундж) здався", "3cac7dd2"], "d": ["Трьохсотлітня династія Фунджів здалася без бою. Табір, заснований того ж року в місці злиття двох рукавів Нілу, невдовзі перетворився на Хартум — адміністративний центр Судану. Інші місця, приєднані того самого дня: Сеннар.", "1ad105c1"]},
"OLAYLAR_EK4:1821-08-19:0":{"b": ["Захоплено Кордофан", "06440602"], "d": ["Друга колона, відправлена на захід, розбила при Барі (Bâra) війська Дарфуру та захопила Кордофан разом з околицями Нухуда. Так єгипетська влада в Судані поширилася з долини Нілу на західні степи.", "6bc3a4f6"]},
"OLAYLAR_EK4:1822-06-28:0":{"b": ["Єгипетські війська висадилися на Криті", "835aee90"], "d": ["Коли грецьке повстання перекинулося на Крит, Висока Порта попросила відправити на острів єгипетські війська. З цього втручання почався вплив Мехмеда Алі на острові, який через вісім років завершився наданням йому намісництва на Криті.", "8d651366"]},
"OLAYLAR_EK4:1822-10-24:0":{"b": ["Убивство Ісмаїл-паші в Шенді", "223860c9"], "d": ["Місцевий емір Німр, розлючений вимогами тяжких податків і солдатів, підпалив будинок, де зупинився Ісмаїл-паша, і спалив його разом із почтом. Каральний похід перетворив край на криваве озеро; відтоді управління Суданом ґрунтувалося на жорстокості.", "722af711"]},
"OLAYLAR_EK4:1824-07-19:0":{"b": ["Махмуд II попросив у Мехмеда Алі допомоги щодо Мореї", "03594a42"], "d": ["Через морейське повстання, яке яничарське військо не могло придушити три роки, султан звернувся до єгипетського війська, навченого за європейським зразком. Натомість було обіцяно намісництво в Мореї та Крит. Це прохання стало першим відкритим визнанням того, що імперія опинилася в залежності від власної провінції.", "1b0ee342"]},
"OLAYLAR_EK4:1825-02-24:0":{"b": ["Ібрагім-паша висадився в Модоні", "9c993dba"], "d": ["Десант під захистом єгипетського флоту ступив на південно-західний край Мореї. Це військо, оснащене регулярною (нізамі) піхотою та польовою артилерією, швидко здобуло перевагу над повстанськими загонами.", "edf38fca"]},
"OLAYLAR_EK4:1825-06-22:0":{"b": ["Триполіцу відвойовано — центр Мореї впав", "8a478c11"], "d": ["Із падінням Триполіци, адміністративного центру повстання, більша частина Мореї знову опинилася під контролем. На карті півострів позначено васальним тоном, оскільки він у руках єгипетських військ.", "e7d9b818"]},
"OLAYLAR_EK4:1826-04-22:0":{"b": ["Міссолонгі (Месолонгіон) впав", "07257f87"], "d": ["Місто взяли після річної облоги. Проте відгук, який його оборона викликала в європейській пресі, підняв співчуття до грецької справи до найвищої точки й підготував ґрунт для втручання великих держав.", "9bf1efc2"]},
"OLAYLAR_EK4:1827-06-05:0":{"b": ["Афінський Акрополь здався", "3b19f946"], "d": ["Із падінням Акрополя грецьке повстання у воєнному сенсі майже скінчилося. Саме в цей момент справа перестала бути внутрішнім бунтом і стала предметом європейської дипломатії.", "e096fc52"]},
"OLAYLAR_EK4:1827-07-06:0":{"b": ["Лондонський договір: три держави нав'язали грецьку автономію", "7ce46fd8"], "d": ["Британія, Франція та Росія вирішили діяти спільно, щоб змусити османів і греків прийняти перемир'я та умову автономії; було оголошено, що в разі відмови втрутяться їхні флоти. Висока Порта відхилила пропозицію.", "8382f516"]},
"OLAYLAR_EK4:1828-08-06:0":{"b": ["Александрійська конвенція: рішення Єгипту піти з Мореї", "cc978f37"], "d": ["Мехмед Алі, який втратив флот під Наварином, не порадившись зі Стамбулом, домовився безпосередньо з британським адміралом і погодився вивести свої війська з Мореї. Те, що намісник уклав окрему угоду з великими державами, було провісником майбутньої кризи.", "9430ea24"]},
"OLAYLAR_EK4:1828-10-05:0":{"b": ["Єгипетські війська залишили Морею", "8fb742dd"], "d": ["Останні частини посадили на кораблі; півострів фактично було втрачено, а за Лондонським протоколом 1830 року він став ядром незалежної Греції. Мехмед Алі ж не отримав обіцяного намісництва в Мореї і натомість втратив великий флот та військо. Інші поселення, втрачені того самого дня: Модон, Корон.", "7bfbefe0"]},
"OLAYLAR_EK4:1830-11-01:0":{"b": ["Управління Критом залишено Мехмедові Алі", "7f76396d"], "d": ["Як компенсацію за втрату Мореї Мехмедові Алі надали намісництво на Криті. Десять років островом керували з Каїра; на карті весь цей час його позначено васальним тоном. Інші місця, приєднані того самого дня: Кандія (Крит).", "5b000d2b"]},
"OLAYLAR_EK4:1831-10-31:0":{"b": ["Ібрагім-паша вступив до Сирії — почалася перша криза", "1a5cc386"], "d": ["Приводом став намісник Акки, який не повертав фелахів, що втекли з Єгипту; справжньою причиною була потреба Мехмеда Алі в сирійському лісі, портах і людських ресурсах. Військо перетнуло Синай і швидко захопило палестинське узбережжя.", "9d41b0f9"]},
"OLAYLAR_EK4:1831-11-26:0":{"b": ["Почалася облога Акки", "b211d96d"], "d": ["Фортеця, яка 1799 року зупинила Наполеона, трималася шість місяців. Облога стала першим великим випробуванням сучасної артилерії єгипетського війська.", "97d9816b"]},
"OLAYLAR_EK4:1832-05-27:0":{"b": ["Акка впала", "0f47917b"], "d": ["Коли батареї, що били по мурах, пробили пролом, фортецю взяли. Брама Сирії відчинилася; у ті самі дні Висока Порта оголосила Мехмеда Алі бунтівником і скасувала його намісництво.", "f92b4224"]},
"OLAYLAR_EK4:1832-06-16:0":{"b": ["Дамаск здався", "48da3b62"], "d": ["Місто здалося без бою. Ібрагім-паша намагався здобути місцеву підтримку, проголосивши податковий порядок і рівність, надану немусульманам; через кілька років та сама політика стане також причиною повстань проти нього. Інші місця, приєднані в ті самі дні: Бейрут, Триполі (Сирійський), Сайда.", "c67bd97e"]},
"OLAYLAR_EK4:1832-07-08:0":{"b": ["Битва під Хомсом", "867810ee"], "d": ["Османське військо, послане рятувати Сирію, було розгромлене у відкритому полі. Виявилося, що нова армія, створена через шість років після скасування яничарського корпусу, ще не готова.", "f429ba2e"]},
"OLAYLAR_EK4:1832-07-15:0":{"b": ["Захоплено Алеппо", "9c0ead76"], "d": ["Упав і торговельний та адміністративний центр Північної Сирії. Так єгипетське військо підступило до передгір'їв Тавру та повернуло до перевалів біля брами Анатолії.", "b8b4a1bd"]},
"OLAYLAR_EK4:1832-07-29:0":{"b": ["Поразка на перевалі Белен (Бейлан) — відкрилася Чукурова", "4bae872b"], "d": ["Оборонну лінію прорвано у вузькому проході в горах Аманос. Антакья, Адана та Тарсус перейшли до єгипетських військ (окупація Мараша, за TDV, припадає на 1833 рік і є окремим записом); на карті Чукурова переходить у васальний тон. Шлях углиб Анатолії тепер лишився беззахисним.", "73cb1c5e"]},
"OLAYLAR_EK4:1832-09-13:0":{"b": ["Гюлецький перевал впав — узбережжя Ічеля (Мерсін, Сіліфке) опинилося під єгипетським контролем", "d9049b5b"], "d": ["Гюлецький перевал, чукуровська брама Тавру, потрапив до рук єгипетського війська. Ібрагім-паша призначив у санджак Ічель власного мютеселліма, і всі пристані узбережжя опинилися під єгипетським контролем. На карті Мерсін і Сіліфке позначено як підпорядковані Єгипту від цього дня (нижня межа; дня призначення в джерелі немає); оскільки за кютахійським рішенням передавалося лише мухассильство Адани, цей контроль припиняється з евакуацією Анатолії.", "fa650158"]},
"OLAYLAR_EK4:1832-09-13:1":{"b": ["Ереглі (біля Коньї) під єгипетською окупацією — таврський вихід шляху Конья — Адана", "fb908900"], "d": ["Ереглі, що лежить на шляху до Коньї єгипетського війська, яке перейшло Гюлецький перевал, 1832 року окупував Ібрагім-паша, а після евакуації за кютахійським врегулюванням 1833 року місто знову приєднали до провінції Караман. На карті це підтверджена джерелом проміжна точка лінії окупації між Аданою та Коньєю; щодо Улукишли та Карапинара свідчень на рівні міста не знайдено.", "c5c7c153"]},
"OLAYLAR_EK4:1832-11-21:0":{"b": ["Єгипетське військо вступило до Коньї", "13952a2d"], "d": ["Військо, що перейшло Тавр, дісталося Центральної Анатолії. Сили османського намісника вперше просувалися корінними землями імперії. Інші місця, приєднані того самого дня: Караман.", "569bd202"]},
"OLAYLAR_EK4:1832-12-21:0":{"b": ["Битва під Коньєю: великий візир потрапив у полон", "ec82cc9a"], "d": ["Османське військо, розсіяне в тумані, зазнало тяжкої поразки, а великий візир Решід Мехмед-паша потрапив у полон. Центрального війська держави більше не існувало; між Стамбулом та єгипетськими військами не лишилося сили, яка могла б стати на заваді.", "30e73138"]},
"OLAYLAR_EK4:1833-01-01:0":{"b": ["Мараш окуповано єгиптянами", "f558e383"], "d": ["За TDV, 1833 року Мараш окупував Кавалали Ібрагім-паша, і місто майже дев'ятнадцять місяців залишалося під його управлінням. Оскільки Мараш лишався поза провінційними межами кютахійського врегулювання, це управління є фактичним, а не юридичним.", "3d3c898a"]},
"OLAYLAR_EK4:1833-01-01:1":{"b": ["Карахісар-і Сахіб (Афьон) окуповано єгиптянами — шлях Конья — Кютах'я", "ae0c2c78"], "d": ["Карахісар-і Сахіб, що лежав на шляху єгипетського війська, яке після битви під Коньєю просувалося до Кютах'ї, 1833 року деякий час перебував у руках Ібрагім-паші. На карті це підтверджена джерелом проміжна точка лінії окупації між Коньєю та Кютах'єю; щодо Акшехіра, Илгина та Ісхакли свідчень на рівні міста не знайдено, тому їх позначено османським кольором.", "bce0b466"]},
"OLAYLAR_EK4:1833-02-02:0":{"b": ["Єгипетське військо дійшло до Кютах'ї", "214f8df6"], "d": ["Ібрагім-паша зупинився в Кютах'ї, за три переходи від Стамбула. Те, що він не пішов далі, мало не воєнні, а політичні причини: враховано було російське втручання та реакцію Європи.", "0f1c5f03"]},
"OLAYLAR_EK4:1833-02-20:0":{"b": ["Російський флот біля Бюйюкдере", "6f836d61"], "d": ["Махмуд II, не отримавши допомоги від Британії та Франції, звернувся до вчорашнього ворога — Росії. Це рішення, яке пам'ятають за висловом султана «хто тоне, той і за змію хапається», призвело до висадки російських військ на протоках і викликало тривогу в Європі.", "3e402e00"]},
"OLAYLAR_EK4:1833-05-06:0":{"b": ["Кютахійська домовленість (усна) — Сирія та Адана дістаються Кавалали", "25fe9985"], "d": ["Висока Порта залишила Мехмедові Алі, крім Єгипту, Криту та Хіджазу, також намісництва Дамаска, Алеппо, Триполі (Сирійського) та Сайди, а мухассильство Адани — Ібрагім-паші. Натомість військо відійшло на південь від Тавру. Це був не договір, а фірмани, видані султаном намісникові, — питання не було розв'язане, а лише відкладене.", "4160e4f4"]},
"OLAYLAR_EK4:1833-06-15:0":{"b": ["Відхід єгипетського війська з Анатолії завершено через Гюлек", "a53ac2a3"], "d": ["Після кютахійського врегулювання єгипетські війська залишили Анатолію; приблизно до середини червня все військо перейшло Гюлецьким перевалом у Чукурову. Узбережжя Ічеля (Мерсін, Сіліфке) повертається під османське управління; мухассильство Адани та Сирія залишаються за Єгиптом.", "c5e13625"]},
"OLAYLAR_EK4:1833-07-08:0":{"b": ["Ункяр-Іскелесійський договір", "da741d5c"], "d": ["З Росією підписано восьмирічний союз про взаємну оборону. За таємною статтею османи в разі нападу на Росію мали закрити протоки для воєнних кораблів. Це стало одним із найсуперечливіших рішень османської дипломатії та спонукало Британію активно втрутитися в єгипетське питання.", "43dc2c96"]},
"OLAYLAR_EK4:1834-05-19:0":{"b": ["Палестинсько-наблуське повстання проти єгипетського управління", "4fe43e27"], "d": ["Примусовий набір до війська, вилучення зброї та нові податки спричинили в Палестині широке повстання. Його жорстоко придушили; підтримка єгипетського управління серед місцевого населення швидко танула.", "2a3301a2"]},
"OLAYLAR_EK4:1834-08-01:0":{"b": ["Кінець єгипетського управління Марашем (приблизно)", "bb46ca42"], "d": ["Якщо відлічувати від окупації 1833 року термін «майже дев'ятнадцять місяців», названий у TDV, єгипетське управління закінчується приблизно влітку 1834 року. Те, що Мустафа-бей із роду Кючюкаліогуллари 1834 року, не здолавши чинити опір єгипетському війську, відступив у бік Мараша, також показує, що тоді Мараш був притулком поза єгипетським контролем.", "fbb6814a"]},
"OLAYLAR_EK4:1837-10-15:0":{"b": ["Повстання в Джебель-ад-Друз", "12e74626"], "d": ["Опір, що спалахнув у друзькому краї, тривав два роки. Невдоволення, яке накопичилося в Сирії, 1840 року, коли союзні флоти підійшли до узбережжя, залишило тил єгипетського війська оголеним.", "75c50707"]},
"OLAYLAR_EK4:1838-05-25:0":{"b": ["Мехмед Алі заявив про намір здобути незалежність", "48633bbd"], "d": ["Намісник повідомив консулам великих держав, що думає проголосити незалежність Єгипту та Сирії. Британія рішуче виступила проти: поява в Середземномор'ї сильної та близької до Франції держави загрожувала б шляху до Індії.", "d6181bd9"]},
"OLAYLAR_EK4:1839-04-21:0":{"b": ["Османське військо перейшло Євфрат", "9af1ea69"], "d": ["Махмуд II рушив своє військо до сирійського кордону, щоб повернути втрачене за Кютах'єю. Прусський офіцер Мольтке, який перебував при війську радником, заперечував проти вибору позиції та передчасного наступу; до його заперечень не дослухалися.", "85d5db1c"]},
"OLAYLAR_EK4:1839-06-24:0":{"b": ["Битва під Нізібом — османське військо розсіялося", "156b3cdf"], "d": ["Невдало розташоване османське військо було розгромлене за кілька годин. Султан помер раніше, ніж звістка про поразку дійшла до Стамбула; за кілька днів держава втратить військо, володаря, а потім і флот.", "fb8af82d"]},
"OLAYLAR_EK4:1839-06-28:0":{"b": ["Смерть Махмуда II", "07eccfff"], "d": ["Султан, який за тридцять один рік правління скасував яничарський корпус і відбудував центральне управління, помер, так і не здолавши свого найбільшого супротивника. Його хворобу не вдалося правильно діагностувати. Із побоювання, що пробудиться яничарський дух, смерть приховували до 30 червня, доки в місті не вжили військових заходів.", "3174d901"]},
"OLAYLAR_EK4:1839-07-01:0":{"b": ["Сходження на престол Абдул-Меджида та похорон Махмуда II", "d0f3d2cc"], "d": ["Після смерті батька на престол зійшов шістнадцятирічний Абдул-Меджид. Того самого дня тіло Махмуда II доставили до палацу Топкапи; очікуваних заворушень не сталося, і до похоронної процесії приєдналися широкі маси мусульман і немусульман.", "7b398ea4"]},
"OLAYLAR_EK4:1839-07-14:0":{"b": ["Передача флоту в Александрії", "a53e6103"], "d": ["Капудан-паша (капітан-і дер'я) Ахмед Февзі-паша, підозрюючи, що великий візир Коджа Хюсрев-паша віддасть флот Росії, повів ескадру до Александрії й передав її Мехмедові Алі. За один місяць Османська держава залишилася без війська, без султана і без флоту.", "78a26255"]},
"OLAYLAR_EK4:1839-07-27:0":{"b": ["Спільна нота великих держав", "2a3b8316"], "d": ["П'ять держав вручили Високій Порті ноту з вимогою не укладати самостійно угоди в єгипетському питанні. Так внутрішня справа офіційно стала «європейським питанням»; Османська держава фактично втратила право вирішувати долю власної провінції.", "979e7f0a"]},
"OLAYLAR_EK4:1840-07-15:0":{"b": ["Лондонський договір: чотири держави на боці османів", "a517f775"], "d": ["Договір, підписаний без участі Франції, висунув Мехмедові Алі ультиматум: якщо погодиться за десять днів — спадкове намісництво в Єгипті та довічне володіння Аккою; якщо за двадцять днів — лише Єгипет; якщо відмовиться — нічого. Намісник відмовився.", "fc066f82"]},
"OLAYLAR_EK4:1840-09-10:0":{"b": ["Бомбардування Бейрута та висадка союзників", "0905ce92"], "d": ["Британсько-австрійський флот обстріляв Бейрут; населенню, яке повстало проти єгипетського управління в горах Лівану, роздали зброю. Контроль Ібрагім-паші над Сирією розвалився між внутрішнім повстанням і зовнішнім втручанням.", "743ec7e2"]},
"OLAYLAR_EK4:1840-10-10:0":{"b": ["Бейрут і прибережні міста втрачено", "09bdaf23"], "d": ["Після боїв у напрямку Баальбека єгипетські війська відійшли від узбережжя. На карті ліванське узбережжя виходить із васального тону й повертається під пряме османське управління.", "fe5e95aa"]},
"OLAYLAR_EK4:1840-11-03:0":{"b": ["Акка впала за дві години", "5aec21f0"], "d": ["Під час бомбардування союзною ескадрою вибухнув пороховий склад фортеці, і за кілька годин Акка здалася. Фортеця, яку вісім років тому Ібрагім-паша зміг узяти за шість місяців, продемонструвала перевагу корабельної артилерії.", "5cf01edf"]},
"OLAYLAR_EK4:1840-11-27:0":{"b": ["Александрійська конвенція", "85cb47b0"], "d": ["Мехмед Алі погодився відмовитися від Сирії, Адани, Криту та Хіджазу, повернути османський флот і визнати верховенство султана; натомість йому гарантували спадкове намісництво в Єгипті.", "63d90626"]},
"OLAYLAR_EK4:1841-02-25:0":{"b": ["Єгипетське військо залишило Сирію та Чукурову", "719a28dc"], "d": ["Дев'ятирічна окупація скінчилася; військо Ібрагім-паші повернулося до Єгипту через Синай. На карті широка смуга від Алеппо до Гази та від Адани до Криту знову переходить під пряме османське управління. Інші поселення, втрачені того самого дня: Урфа, Мараш, Тарсус, Антакья, Кандія (Крит), Хама, Дамаск, Єрусалим, Яффа, Наблус.", "a678b17a"]},
"OLAYLAR_EK4:1841-05-24:0":{"b": ["Фірман: намісництво в Єгипті залишено спадковим для роду Кавалали", "87b89ff8"], "d": ["Фірман султана визнав, що намісництво переходить у межах династії від батька до сина; натомість чисельність війська скоротили до вісімнадцяти тисяч, податки прив'язали до Стамбула, а право карбувати монету та укладати договори скасували. Єгипет залишився провінцією, але тепер був володінням окремої династії. Управління Хіджазом і Харамейном повернулося до Високої Порти. Інші поселення, що того самого дня повертаються з васального шару в прямий: Мекка, Медина, Джидда, Янбу.", "48099454"]},
"OLAYLAR_EK4:1841-07-13:0":{"b": ["Лондонська конвенція про протоки", "0e95a1ea"], "d": ["Конвенція, що замінила Ункяр-Іскелесійський договір, постановила, що в мирний час протоки закриті для всіх воєнних кораблів. Привілей, здобутий Росією самостійно, перетворився на спільну гарантію Європи; питання проток дістало міжнародний статус.", "5bbbb459"]},
"OLAYLAR_EK4:1848-09-01:0":{"b": ["Ібрагім-паша фактично став намісником Єгипту", "9e14f5d9"], "d": ["Замість постарілого Мехмеда Алі, який втрачав розумові здібності, намісником призначили його сина Ібрагім-пашу. Однак через кілька місяців, у листопаді 1848 року, він помер раніше за батька.", "338908f8"]},
"OLAYLAR_EK4:1849-08-02:0":{"b": ["Смерть Кавалали Мехмеда Алі-паші", "871310e0"], "d": ["Намісник, який народився в Кавалі, заснував династію в Єгипті та двічі підводив імперію до краю прірви, помер у віці вісімдесяти років. Заснована ним династія правила Єгиптом до 1953 року; держава ж, побачивши, що змогла загоїти завдану ним рану лише завдяки європейському втручанню, рушила шляхом Танзимату.", "c0877894"]},
"OLAYLAR_EK5:1281-01-01:0":{"b": ["Смерть Ертогрула-газі та перехід бейлику до Осман-бея — спадщина Сьогюта й Доманича", "395fb9fa"], "d": ["За TDV, Ертогрул-газі помер 680 (1281–82) року; у статті зазначено, що наводять також дати 1288 та 1289 роки. Осман-бей успадкував від батька не завойоване місто, а два наділи, які сельджуцький султан дав Ертогрулу, поселеному на найпередовішій лінії прикордоння: зимівник (юртлук) у Сьогюті та літнє пасовище (яйлак) у Доманичі. Тобто бейлик почав свою справу не зі спадщини завоювань, а з двох пасовищних наділів; на карті ці два місця позначено не як «завоювання», а як «спадщину».", "37fbc33c"]},
"OLAYLAR_EK5:1285-01-01:0":{"b": ["Напад на Куладжахісар — перша воєнна операція Осман-бея", "79b00b14"], "d": ["Стаття TDV «Осман I»: «Він пограбував і підпалив невелику фортецю Куладжа поблизу Інегьоля (684/1285)». Це перша воєнна дія Осман-бея, яку можна датувати за джерелами. Жодного поселення не було захоплено назавжди, фортецю пограбовано та спалено; отже, це радше класичний прикордонний набіг, ніж завоювання. Його вважають початком воєнної діяльності бейлику.", "15ee9a09"]},
"OLAYLAR_EK5:1288-01-01:0":{"b": ["Завоювання Караджахісара — перше міське здобуття та панування над Ескішехіром", "178ae619"], "d": ["Стаття TDV «Осман I»: 687 (1288) року Осман-бей «завоював Караджахісар і став володарем Ескішехіра». Це перше справжнє міське здобуття бейлику, і за переказом саме цим успіхом Осман-бей піднявся до санджакбейства на прикордонні; розповідають, що в Караджахісарі вперше прочитали п'ятничну хутбу на його ім'я і сюди призначили першого каді. Стаття TDV «Ескішехір» зазначає, що османська традиція наводить 1291 рік, але його точність сумнівна.", "90949e22"]},
"OLAYLAR_EK5:1299-01-01:0":{"b": ["Завоювання Біледжика та Ярхісара нічним нападом", "f461b0af"], "d": ["Стаття TDV «Біледжик»: «Хоча інші текфури краю, серед них і біледжицький, готували замах на Осман-газі, коли про цю змову стало відомо, османські сили раптовим нападом завоювали Ярхісар і Біледжик (1299)». Дві фортеці взяли за одну операцію, під час одного нічного нападу. Цю дату як рік заснування Османської держави вважають переломною. Інші місця, приєднані того самого дня: Інегьоль.", "ec452c9e"]},
"OLAYLAR_EK5:1302-07-27:0":{"b": ["Битва під Коюнхісаром (Бафеєм) — перша велика перемога над візантійським військом", "584a9512"], "d": ["Стаття TDV «Осман I»: 27 липня 1302 року Осман-бей дав бій візантійському війську під Бафеєм (Коюнхісаром) і переміг його. Ця перемога стала переломною: Осман-бей із регіонального прикордонного бея піднявся до статусу засновника династії. Після битви Бурсинська рівнина опинилася під османським контролем і почалася блокада Нікеї.", "b82fb787"]},
"OLAYLAR_EK5:1303-01-01:0":{"b": ["Перемога під Дімбосом і подальше взяття Кіте та Улубата", "e168ab64"], "d": ["Стаття TDV «Осман I»: 702 (1303) року союз, укладений текфурами Бурси, Кестеля, Кіте та Адраноса, було розгромлено в Дімбоській ущелині; ворога з боями відтіснили аж до вузького проходу, а текфур Кестеля загинув на полі битви. Одразу після перемоги захопили фортеці Кіте та Улубат, перерізавши сухопутний зв'язок Бурси й посиливши її блокаду. У цій битві брав участь і молодий Орхан.", "4afb53bf"]},
"OLAYLAR_EK5:1304-01-01:0":{"b": ["Сакарійський похід: взяття Леблебіджіхісара, Лефке, Мекедже та Гейве", "a51ba4d3"], "d": ["Стаття TDV «Осман I» наводить послідовність Сакарійського походу 704 (1304) року: «Коли він прийшов до фортеці Леблебюджі, текфур скорився... Він прибув до Лефке... Дійшов до Мекедже... Пішов до Гейве й узяв фортецю, яку застав порожньою». Лефке — це брама долини Сакар'ї, відкрита в бік Біледжика. Цей єдиний похід, поставивши під османський контроль ланцюг фортець уздовж долини, замкнув східний фланг Нікейської улоговини.", "ae2866c2"]},
"OLAYLAR_EK5:1305-01-01:0":{"b": ["Завоювання фортець Гейвської ущелини: Карачепюш, Каратігін та Абсу", "76907c78"], "d": ["Стаття TDV «Орхан»: під час Сакарійського походу 705 (1305) року Орхан «завоював фортеці Карачепюш (Katoikia), Каратігін перед Нікеєю та Абсу (Hypsu: у Гейвській ущелині)». Ці три фортеці, перекривши прохід між долиною Сакар'ї та Нікейською улоговиною, повністю відрізали суходільну допомогу Нікеї. У Карачепюші та Абсу в Гейвській ущелині оселили Газі Абдуррахмана; тепер місто можна було взяти лише голодом.", "d330595f"]},
"OLAYLAR_EK5:1323-09-01:0":{"b": ["Похід на Адранос (Орханелі) — останній похід Осман-бея", "4811546c"], "d": ["Стаття TDV «Орхан» фіксує похід на фортецю Адранос восени 1323 року як останній похід Осман-бея. Текфур Адраноса був учасником союзу текфурів, укладеного проти османів під Дімбосом двадцятьма роками раніше; цей похід означав зведення того рахунку. Точний день завоювання фортеці невідомий; операцію продовжив Орхан-бей.", "1e8ea25a"]},
"OLAYLAR_EK5:1329-06-01:0":{"b": ["Битва під Пелеканоном (Мальтепе) та взяття всієї Коджаелі", "389e7bd4"], "d": ["Стаття TDV «Орхан»: у перший день битви Орхан-газі відправив загін із трьохсот людей, щоб виманити візантійське військо на себе; другого дня битва розгорілася, коли частини під командуванням Пазарлу спустилися на рівнину, а коли імператора поранило стрілою, у візантійському війську почалася паніка. Результат вирішальний: «Орхан захопив усю Коджаелі; після перемоги в нікейців не лишилося жодної надії». Прибережні містечка від Хереке до Ускюдара перейшли під османську владу, а Гебзе зробили центром краю. Це було останнє візантійське імператорське військо, яке прийшло рятувати Константинополь.", "73fe4332"]},
"OLAYLAR_EK5:1333-08-01:0":{"b": ["Візантію зроблено данницею — облога Ізміта та угода", "0c1ec8d3"], "d": ["Стаття TDV «Орхан»: улітку 733 (1333) року Орхан обложив Ізміт великим військом із катапультами, і імператор пристав на угоду. За відмову від облоги Візантія погодилася платити Орханові 12 000 золотих (гіперпірів) на рік; «таким чином в очах османського еміра Візантія опинилася в становищі країни-данниці». Натомість Орхан мав бути другом імператора й не нападати на підвладні Візантії міста. Те, що прикордонний бейлик обклав даниною Східний Рим, було оголошенням того, наскільки змінилося співвідношення сил.", "e2e3eeb4"]},
"OLAYLAR_EK5:1345-01-01:0":{"b": ["Анексія бейлику Карасі: Баликесір, Бергама, Біга, Едреміт та Ердек", "c7cb0511"], "d": ["Стаття TDV «Орхан» (Іналджик) відносить анексію до 735 (1334–35) року: після смерті Демірхан-бея гази Карасі та Хаджі Ільбей запросили на престол Дурсун-бея й попросили в Орхана допомоги. Орхан спершу рушив на Баликесір; коли Дурсун-бея, який пішов на мирні переговори, убила стріла, випущена з Бергамської фортеці, бейлик повністю приєднали до османських володінь. Під час тієї самої операції скорилися Кірмасті та Міхаліч, взяли Гьольязи, а Улубат, раніше залишений на умовах гарантії безпеки (аман), остаточно захопили. Орхан призначив у санджак Карасі Сулейман-пашу та зробив Бігу прикордонним центром — так здобули морські кадри для переправи в Румелію. Примітка: стаття TDV «Каресіогуллари» для тієї самої події наводить 746 (1345) рік; енциклопедія суперечить сама собі. Інші місця, приєднані того самого дня: Чанаккале.", "f5ed82c2"]},
"OLAYLAR_EK5:1381-04-01:0":{"b": ["Тимур узяв Герат: кінець династії Куртів і перехід Хорасану до Тимуридів", "15f6019e"], "d": ["1380 року Хорасан був роздроблений боротьбою між сербедарами, Куртами та Музаффаридами. Відправивши в цей край сина Міран-шаха, Тимур сам вирушив на Герат і після певної облоги прийняв місто від меліка з роду Куртів Гіяс ад-Діна Пір Алі. Повстання, що спалахнуло після його відходу, Міран-шах утопив у крові, і династії Куртів, яка правила в Гераті з 1255 року, настав кінець. Увесь Хорасан від Мешхеда до Нішапура того часу перейшов під владу Тимуридів.", "6ae06d43"]},
"OLAYLAR_EK5:1386-01-01:0":{"b": ["«Трирічний похід» Тимура: завоювання Азербайджану та Північного Ірану", "2a98ec51"], "d": ["Тимур, який під час хорасанських походів зблизька побачив роздрібненість Ірану, 788 (1386) року рушив на захід. Під час походу 1386–1388 років, відомого як «трирічний похід», він через Мазендеран, Лурестан і Грузію перейшов в Азербайджан і дістався Карабаху; Тебриз, Ардебіль, Урмія та Нахічевань перейшли під владу Тимуридів. Захоплення Північного Ірану та Азербайджану стало також початком тривалого суперництва із Золотою Ордою, як колись між улусом Джучі та ільханами.", "aaf3b558"]},
"OLAYLAR_EK5:1393-01-01:0":{"b": ["Кінець династії Музаффаридів: поразка шаха Мансура під Ширазом", "5fd14eb8"], "d": ["Шах Мансур, останній сильний володар Музаффаридів, які з 1318 року правили в Єзді, Фарсі, Ісфагані та Кермані, об'єднавшись із родичами, виступив проти Тимура. У битві поблизу Шираза, коли один із його емірів перейшов на бік ворога, він утратив більшість своїх сил, зазнав поразки й був убитий. Оскільки Тимур згодом наказав стратити й усіх членів династії, панування Музаффаридів скінчилося, а Фарс і Керман приєднали до володінь Тимуридів.", "8e89c2dc"]},
"OLAYLAR_EK5:1393-08-29:0":{"b": ["Тимур захопив Багдад — Джалаїри втекли до Анатолії", "4d5602b3"], "d": ["Тимур після тривалої облоги захопив Багдад; правитель міста султан Ахмед Джалаїр утік на захід і знайшов притулок спершу в мамлюків, а потім при османському дворі. Так експансія Тимура на захід уперше безпосередньо зіткнулася з османською сферою впливу. Звідси починається перша ланка ворожнечі між двома володарями.", "2fac674f"]},
"OLAYLAR_EK5:1399-11-01:0":{"b": ["Виклик Тимура: відмова видати втікачів", "33790bc8"], "d": ["Під тиском Тимура султан Ахмед Джалаїр і вождь Кара-Коюнлу Кара Юсуф знайшли притулок в османських землях; Тимур зажадав видати обох утікачів, а Баязид Блискавичний відмовив. Після цього обидва володарі почали обмінюватися листами, сповненими взаємних тяжких образ. Ідейний ґрунт війни було закладено цим листуванням ще до того, як рушив хоч один солдат.", "ac66be59"]},
"OLAYLAR_EK5:1400-08-01:0":{"b": ["Тимур зрівняв Сівас із землею", "f4d79de6"], "d": ["Тимур, який вирушив на Сівас, маючи за провідників Кара-Юлюк Осман-бея з Ак-Коюнлу та ерзінджанського еміра Мутаххартена, обложив місто на вісімнадцять днів і, прийнявши капітуляцію з обіцянкою не проливати нічиєї крові, вчинив велику різанину; захисників наказав скинути в рови й засипати живцем. Важливі споруди міста, насамперед мури, зруйнували, і Сівас демографічно занепав. Це був перший великий удар Тимура по османських землях, за два роки до Анкарської битви.", "8ddb3e3a"]},
"OLAYLAR_EK5:1401-02-01:0":{"b": ["Баязид Блискавичний повернув Ерзінджан і Кемах", "7047ca08"], "d": ["Скориставшись тим, що Тимур вирушив у сирійський похід, Баязид Блискавичний відібрав Ерзінджан і Кемах в ерзінджанського еміра Мутаххартена, підвладного Тимурові. Хоча він не втрутився в руйнування Сіваса, цей крок означав прямий виклик сфері впливу Тимура у Східній Анатолії. Відтоді стосунки двох володарів стали непоправними.", "2160d645"]},
"OLAYLAR_EK5:1402-03-13:0":{"b": ["Ультиматум Тимура з Тебриза — чотири умови", "3e1ac50e"], "d": ["Через посла, відправленого з Тебриза, Тимур висунув чотири умови: повернути Кемах Мутаххартенові, віддати власникам землі, відібрані в анатолійських беїв, прислати заручником османського царевича та прийняти шапку (кюлах) і пояс як знаки васальної залежності, а також видати Кара Юсуфа. Баязид не прийняв жодної; попри наполягання сановників і посередництво Мутаххартена, переговори зірвалися. Перш ніж вирушити в китайський похід, Тимур був сповнений рішучості остаточно закрити анатолійське питання.", "bd475bc3"]},
"OLAYLAR_EK5:1402-08-17:0":{"b": ["Бейлик Саруханогуллари відновлено — Маніса вийшла з-під османської влади", "ac747b05"], "d": ["Через три тижні після анкарського розгрому за підтримки Тимура бейлик очолив Орхан-бей, і земля Саруханів знову стала незалежною. Край із центром у Манісі зник з османської карти через дванадцять років після анексії 1390 року. Це одне з перших точно датованих застосувань Тимурової політики відродження бейликів.", "9fe5744d"]},
"OLAYLAR_EK5:1402-08-20:0":{"b": ["Емір Сулейман утік до Румелії з державною скарбницею", "0a2b7363"], "d": ["Емір Сулейман, прихопивши із собою державну скарбницю в Бурсі, архіви, родину та братів, переправився кораблем із Гемліка до Гюзельджехісара (Анадолухісари), звідти дістався Галліполі й проголосив себе володарем в Едірне. Перенесення державного архіву та скарбниці в Румелію стало початком зміщення османського центру ваги на Балкани на ціле покоління. На карті від цієї дати Румелію зображено власним кольором еміра Сулеймана.", "393aa053"]},
"OLAYLAR_EK5:1402-09-15:0":{"b": ["Тимур відновив анатолійські бейлики — тюркська єдність розпалася", "15187774"], "d": ["Після перемоги під Анкарою Тимур повернув беям, які були при ньому, їхні колишні землі. Мехмед-бей та Алі-бей з роду Караманогуллари отримали Караманську землю разом із Кайсері, Киршехіром, Сіврихісаром і Бейшехіром; Гермія́ногуллари Якуб-бей II — Кютах'ю та Гермія́нську землю; Джандарогли Ісфендіяр-бей — на додачу до лінії Кастамону — Синоп ще Чанкири та Каледжик. Землі Айдин, Ментеше та Теке також повернулися до колишніх династій. Анатолійська тюркська єдність, яку Баязид Блискавичний будував десять років, розпалася за одне літо; на карті ці бейлики знову з'являються у власних кольорах. Інші поселення, що тоді ж перейшли з рук у руки: Аксарай, Денізлі, Ереглі (Конья), Ерменек, Илгин, Карапинар, Кайсері, Конья, Киршехір, Кютах'я, Сіврихісар, Сьоке.", "0c3d6fbf"]},
"OLAYLAR_EK5:1402-12-14:0":{"b": ["Тимур відібрав Ізмір у лицарів-іоаннітів", "66dd1dd4"], "d": ["Тимур, рушивши на захід через Кютах'ю, Денізлі, Айдин, Аясолук і Тіре, обложив і взяв прибережний Ізмір, який з 1344 року був у руках християн. Швидко захопивши фортецю, яку Баязид Блискавичний роками не міг узяти, і здобувши навколишні укріплення, Тимур залишив землю Айдин колишнім власникам і повернув на схід. Відтоді місто перейшло під управління Айдиногли Джунейд-бея.", "b6c372a5"]},
"OLAYLAR_EK5:1402-12-20:0":{"b": ["Іса Челебі захопив Бурсу — виникла анатолійська частка", "955128c1"], "d": ["Іса Челебі, який після анкарського розгрому відійшов у край Карасі, захопив Бурсу, поки Тимур був в Ізмірі. У колишній столиці, пограбованій і спаленій воїнами Тимура, він проголосив себе володарем і наказав карбувати монети від свого імені; у січні 1403 року в Анатолії його визнавали з титулом «володар турків». На карті ця частка, що тягнеться вздовж азійського берега Мармурового моря, позначена власним кольором Іси Челебі.", "fdd5eed3"]},
"OLAYLAR_EK5:1403-03-15:0":{"b": ["Відхід Тимура з Анатолії", "93a98839"], "d": ["Отримавши звістку, що Баязид Блискавичний помер в Акшехірі, Тимур вирішив, що його справу в Анатолії закінчено, і повернув на схід. По собі він залишив бейлики, які заявили йому про вірність, та посварених між собою османських царевичів; деякі міста, як-от Сівас, залишилися в руках емірів, підвладних Тимурові, таких як Мезід-бей. Тимур більше не повертався до Анатолії, але створений ним роздроблений порядок протримався десять років.", "646cb1bc"]},
"OLAYLAR_EK5:1404-03-01:0":{"b": ["Емір Сулейман переправився в Анатолію: Бурса дісталася йому", "9b27aa5f"], "d": ["Почувши про поразку Іси Челебі, емір Сулейман разом із Чандарли Алі-пашею з сильним військом переправився в Анатолію та захопив Бурсу; записи за березень 1404 року свідчать, що під його владою було й Караденіз-Ереглі. Челебі Мехмед не зміг протистояти Сулейманові, який невдовзі запанував і над Румелією, і над більшою частиною Анатолії. Інші поселення, що тоді ж перейшли від Челебі Мехмеда до еміра Сулеймана: Акьязи, Анадолу-Хісари, Абсу (Hypsu), Адранос (Орханелі), Акхісар (Памукова), Армутлу, фортеця Айдос, Айвалик, Баликесір, Бехрамкале (Ассос), Бергама, Бейкоз, Біга. На карті від цієї дати до повторного взяття Бурси Челебі Мехмедом (1410) обидва береги позначено одним кольором, як частку еміра Сулеймана.", "0fc7e1b4"]},
"OLAYLAR_EK5:1405-01-01:0":{"b": ["Битва на Єнішехірській рівнині — Челебі Мехмед відступив до Амасьї", "f1568288"], "d": ["Челебі Мехмед, утративши Бурсу та Анкару, зазнав поразки від еміра Сулеймана на Єнішехірській рівнині, позбувся всіх своїх здобутків у Західній Анатолії та відступив на базу в Токаті й Амасьї. Після цієї поразки він уникав прямого зіткнення та взявся зміцнювати свою владу в глибині Анатолії. Так почалася найдовша тиха фаза міжцарів'я (фетрету).", "8c8a3c8c"]},
"OLAYLAR_EK5:1406-01-01:0":{"b": ["Емір Сулейман відібрав Анкару в Челебі Мехмеда", "d6a2acd6"], "d": ["1406 року емір Сулейман обложив Анкару, яка після відходу Тимура з Анатолії залишалася в руках Челебі Мехмеда. Комендант фортеці Якуб-бей певний час тримався, але завдяки хитрощам великого візира Чандарли Алі-паші здав фортецю Сулейманові. Тоді Челебі Мехмед домовився з Мехмед-беєм із роду Караманогуллари й виступив проти Сулеймана.", "f2a18bf9"]},
"OLAYLAR_EK5:1671-01-01:0":{"b": ["Початок правління деїв в Алжирі", "e99faa51"], "d": ["Алжирський оджак і таїфе-і реїс (корпорація капітанів-корсарів) змістили останнього агу та обрали деєм Хаджі Мехмеда довічно. Відтоді Алжиром правив не призначений зі Стамбула бейлербей, а дей, якого місцевий оджак обирав із власного середовища; османський зв'язок обмежувався згадуванням імені султана в хутбі та обов'язками, пов'язаними зі стягом і участю в походах. Так Алжир перетворився з еялету на оджаклик — такого самого перетворення зазнали Туніс 1705 року за Хусейнідів і Триполітанія 1711 року за Караманли.", "b8decd95"]},
"OLAYLAR_EK:1300-01-01:0":{"b": ["Взяття Кьопрюхісара та підготовка до заснування Єнішехіра", "39abff03"], "d": ["Захопивши фортеці на перевалах між Бурсою та Ізніком, заклали основу передової ставки, яка мала взяти обидва міста в облогу.", "72fa9808"]},
"OLAYLAR_EK:1301-01-01:0":{"b": ["Заснування Єнішехіра", "d3275837"], "d": ["Для керівництва облогами Бурси та Ізніка було засновано перше регулярне османське гарнізонне поселення; тут народився Орхан Газі.", "39c98a4b"]},
"OLAYLAR_EK:1302-08-01:0":{"b": ["Перша облога Ізніка та завоювання Мармараджика", "cdca2349"], "d": ["Ізнік уперше взяли в облогу, але здобути не змогли (остаточне завоювання — 1331 року); тоді ж взяли сусідню фортецю Мармараджик.", "31c4c65f"]},
"OLAYLAR_EK:1313-01-01:0":{"b": ["Кьосе Міхал приймає іслам і приєднується до османів", "ca0d86e1"], "d": ["Текфур Харманкаї Кьосе Міхал, прийнявши іслам, разом зі своєю фортецею та людьми приєднався до Османа Газі; він став першим османським полководцем візантійського походження.", "327b4cdc"]},
"OLAYLAR_EK:1320-01-01:0":{"b": ["Орхан-бей фактично перебирає правління", "6dadbefc"], "d": ["Через старість і хворобу Османа Газі фактичне керівництво облогою Бурси та походами перейшло до його сина Орхан-бея (офіційне сходження на престол — 1326 року).", "280c6e0d"]},
"OLAYLAR_EK:1324-01-01:0":{"b": ["Перехід Акьязи та острова Імрали в руки османів (дати в джерелах немає)", "380c60ce"], "d": ["За доби Осман-бея (у роки після походу 1305 року) Акьязи стала мішенню османських набігів; точний рік остаточного взяття невідомий. Коли було взято острів Імрали, не повідомляє жодне джерело. Кордон 1324 року на карті є тимчасовим заповнювачем.", "69782c1e"]},
"OLAYLAR_EK:1326-01-01:0":{"b": ["Акча Коджа захопив Кандиру та околиці", "341bb97e"], "d": ["Акча Коджа, один із прикордонних беїв Орхана Газі, здійснюючи набіги на околиці Ізміта зі своєї ставки на захід від озера Сапанджа, близько 1326 року захопив Кандиру та її околиці. Ізміт тоді ще був у руках Візантії; місто впаде лише 1337 року.", "ed042ad1"]},
"OLAYLAR_EK:1326-01-01:1":{"b": ["Приєднання Ялови та Карамюрселя", "133cb07a"], "d": ["Того року Ялова та її околиці на південному узбережжі Ізмітської затоки перейшли в руки турків; прибережну смугу Орхан-бей віддав як тімар Карамюрселу Ґазі.", "592a86bc"]},
"OLAYLAR_EK:1328-01-01:0":{"b": ["Акча Коджа взяв Айдос і замок Самандира", "ce4daa8a"], "d": ["Після взяття Кандири Акча Коджа разом із Конуралпом і Ґазі Абдуррахманом взяв фортецю Айдос поблизу Картала, а потім замок Самандира на північ від неї; Самандирський край віддали йому у власність. Акча Коджа помер 1328 року поблизу Кандири; прикордонне бейство краю передали шехзаде Мураду.", "f2ef1bde"]},
"OLAYLAR_EK:1330-01-01:0":{"b": ["Союз османів, Айдинідів і Саруханідів", "9df6bb74"], "d": ["Три бейліки діяли спільно проти Візантії; флот Умур-бея з роду Айдинідів набігами на фракійське узбережжя виснажував Візантію на другому фронті.", "32ca49ea"]},
"OLAYLAR_EK:1334-01-01:0":{"b": ["Завоювання Гемліка (Кіоса)", "66fc4bcd"], "d": ["Прибережне місто Гемлік (Кіос) біля Гемлікської затоки, що виходить у Мармурове море, перейшло в руки османів. Коли 1326 року здалася Бурса, міського текфура з родиною відіслали до Гемліка; отже, 1326 року Гемлік ще був у руках Візантії. Окремої дати для Армутлу не знайдено; його прив'язано до ланцюга Гемліка.", "27ef02f4"]},
"OLAYLAR_EK:1354-08-01:0":{"b": ["Взяття Анкари", "49bf1f6d"], "d": ["Анкара, якою управляли ахі, перейшла під османське управління; відкрився шлях у Центральну Анатолію. Інші місця, приєднані тоді ж: Сіврігісар, Чанкири.", "eec5d13e"]},
"OLAYLAR_EK:1360-01-01:0":{"b": ["Перерізання шляхів допомоги Едірне: фортеці Чорлу, Люлебургаз, Бабаескі та Кешан", "8e8ad485"], "d": ["Шехзаде Мурад, відновивши завойовницький похід після визволення Халіля, щоб ізолювати Едірне від можливої допомоги ззовні, послав акинджі аж під Константинополь. Було захоплено фортеці Чорлу, Люлебургаз і Бабаескі на дорозі Константинополь—Едірне та Кешан на дорожньому вузлі Південної Фракії. Здача Едірне настала після того, як це кільце облоги було завершене.", "fb171002"]},
"OLAYLAR_EK:1371-09-26:0":{"b": ["Битва під Чірменом — контроль над долиною Мариці", "cd738d8d"], "d": ["Військо сербських володарів було розігнане нічним нападом; місцеві сербські та болгарські володарі в Македонії та Родопах один за одним почали платити данину османам — це був початок не прямого завоювання, а хвилі васалізації. В османській традиції цю битву оповідають також під назвою «Сирпсиндиґи» та під 1364 роком як нічний напад Хаджі Ільбея на військо хрестоносців, що прийшло повернути Едірне; TDV зазначає, що ця дата помилкова і що обидві оповіді стосуються тієї самої битви.", "7b2779cd"]},
"OLAYLAR_EK:1372-06-01:0":{"b": ["Завоювання Пловдива та Старої Загори", "e780c9ae"], "d": ["Було взято Пловдив у горішній частині долини Мариці та Стару Загору на північ від нього; Болгарське царство зробили данником. Шлях Татарпазарджик—Іхтіман між Пловдивом і Софією залишився в руках місцевих володарів, які після Чірмена стали васалами. Інші поселення, втрачені тоді ж: Хасково, Клокотниця.", "019bac28"]},
"OLAYLAR_EK:1381-01-01:0":{"b": ["Ґерміянський посаг: приєднання Кютах'ї", "d6a6fe61"], "d": ["Під час шлюбу Девлетшах-хатун, доньки ґерміянського Сулейман-шаха, з Баязидом Блискавичним Кютах'я, Сімав, Тавшанли та Еґріґьоз перейшли до османів як посаг — класичний приклад розширення без війни. Інші місця, приєднані тоді ж: Афьон.", "3321bbba"]},
"OLAYLAR_EK:1381-06-01:0":{"b": ["Купівля Гамідської землі: приєднання Іспарти", "4a1b6047"], "d": ["Гамідський Хусейн-бей продав частину свого бейліку (Акшехір—Бейшехір—Іспарта) Мураду I за готівку; решту Гамідської землі 1391 року анексує Йилдирим. Інші поселення, втрачені тоді ж: Ісхакли.", "3930685b"]},
"OLAYLAR_EK:1383-09-19:0":{"b": ["Завоювання Серреса", "d4d28b60"], "d": ["Було взято Серрес, ключ до Східної Македонії; Салоніки потрапили в облогове кільце. Лінія Кюстендил—Петрич—Неврокоп—Драма між Софією та Серресом на цю дату ще не була прямо приєднана: вона послідовно перейшла у васалітет у 1370-х—1383 роках, а після 1383 року — під пряме управління. Інші поселення, втрачені тоді ж: Гевгелія, Кілкіс (Авратхісар).", "69be987a"]},
"OLAYLAR_EK:1385-09-01:0":{"b": ["Завоювання Софії", "96d5f01f"], "d": ["Західні перевали Балканських гір було взято під контроль; оскільки на цю дату Серрес перебував під владою вже з 1383 року, землі Фракії та Македонії утворювали нерозривне ціле.", "f358b568"]},
"OLAYLAR_EK:1386-01-01:0":{"b": ["Завоювання Ніша", "77f5d632"], "d": ["Зі взяттям Ніша, замка долини Морави, Сербська деспотовина опинилася під прямою загрозою.", "15f52aaf"]},
"OLAYLAR_EK:1387-04-09:0":{"b": ["Перша здача Салонік", "96010ee9"], "d": ["Після тривалої блокади місто здалося (1403 року його повернуть Візантії, а 1430 року остаточно завоюють). Інші місця, приєднані тоді ж: Кавала. Інші поселення, втрачені тоді ж: Лангадас, Елефтеруполіс (Правіште).", "834119a2"]},
"OLAYLAR_EK:1387-06-08:0":{"b": ["Османо-генуезька ахіднаме — поновлення договору 1352 року", "be11d17a"], "d": ["З генуезькими послами з Пери було поновлено торговельну угоду 1352 року, укладену ще за Орхана Газі; податки між двома державами, поводження з полоненими та вільну торгівлю визначили наново. Це вважають першою офіційно відомою ахіднаме дружби й торгівлі між османами та генуезцями — не військовим союзом, а суто торговельною угодою.", "46b0f65b"]},
"OLAYLAR_EK:1388-01-01:0":{"b": ["Болгарський похід Чандарли Алі-паші: взяття Шумена та Русе", "2781c3a9"], "d": ["Фортеці Болгарського царства вздовж Дунаю було прийнято під владу за один похід; його не слід плутати з поразкою під Білечею в Боснії того ж року — це був одночасний успіх на іншому фронті. Тирново та Відін були останніми болгарськими центрами, що ще трималися.", "d6eaf4cd"]},
"OLAYLAR_EK:1390-01-01:0":{"b": ["Анексія західноанатолійських бейліків: Саруханідів, Айдинідів, Ментеше", "dcc33b71"], "d": ["Три бейліки було приєднано за один раз: осередок Саруханідів — Манісу; осередок Айдинідів — Айдин (разом із верхньою фортецею Ізміра, але портова, нижня, фортеця все ще залишалася в лицарів святого Іоанна — до 1402 року); осередок Ментеше — Муглу та Мілас разом із прибережною смугою Датча—Бодрум—Мармарис—Фетхіє. Егейське узбережжя вперше опинилося в одних руках. Інші місця, приєднані тоді ж: Сьоке.", "7f3094f2"]},
"OLAYLAR_EK:1392-01-01:0":{"b": ["Анексія землі Теке: приєднання Анталії", "fdbeee5c"], "d": ["Землю Теке на середземноморському узбережжі приєднали до османських земель. Текеїди — це гілка, що відокремилася від Гамідидів: Фелекюддін Дюндар-бей залишив завойовану ним Анталію своєму братові Юнусу-бею, і близько 1321 року виник окремий бейлік. Тому після 1321 року Анталію та її околиці на карті показано не кольором Гамідидів, а кольором Текеїдів. Після Анкарської битви бейлік відновили, і остаточно його ліквідували лише 1423 року.", "09a83d97"]},
"OLAYLAR_EK:1392-01-06:0":{"b": ["Завоювання Скоп'є", "9e5a1af5"], "d": ["Було взято осередок Вардарської Македонії; Скоп'є стало одним із головних прикордонних центрів Румелії.", "8722b1dd"]},
"OLAYLAR_EK:1392-11-01:0":{"b": ["Анексія Кастамону", "876330ba"], "d": ["Кастамонську гілку роду Джандаридів було ліквідовано; синопська гілка залишилася васалом. Інші місця, приєднані тоді ж: Бартин, Сафранболу, Акчакоджа, Деврек, Ефлані, Караденіз-Ереглі, Тосья.", "c1158ca8"]},
"OLAYLAR_EK:1393-06-17:0":{"b": ["Падіння Тирнова — анексія Болгарії", "ff666977"], "d": ["Столиця Болгарського царства впала; Болгарія перейшла під пряме османське управління. Інші місця, приєднані тоді ж: Плевен, Ловеч, Габрово.", "c2c12ea0"]},
"OLAYLAR_EK:1393-06-17:1":{"b": ["Фортеця Ловеч перейшла до османів", "a55e87a0"], "d": ["Ловеч, одну з фортець болгарського царя Івана Шишмана, під час походу 1393 року, у якому впало Тирново, разом з іншими провінціями Шишмана приєднали до османських земель. Джерело не говорить напевно: вважають, що завоювання припало на цей рік.", "9430a123"]},
"OLAYLAR_EK:1393-09-01:0":{"b": ["Приєднання Добруджі", "478e36f2"], "d": ["Було приєднано землі Добруджі, що тягнуться до дельти Дунаю. Інші місця, приєднані тоді ж: Силістра, Констанца, Бабадаг, Балчик, Хиршова, Тулча, Мангалія, Ісакча, Тутракан, Мечин, Кючук-Кайнарджа.", "84901de2"]},
"OLAYLAR_EK:1394-01-01:0":{"b": ["Спуск у Фессалію", "8bec60dd"], "d": ["Фессалійську рівнину з осередком у Ларисі (Єнішехірі) взяли під османське управління. Інші місця, приєднані тоді ж: Трикала, Ламія (Іздін).", "d9f2128c"]},
"OLAYLAR_EK:1395-01-01:0":{"b": ["Завоювання Нікополя", "b9791717"]},
"OLAYLAR_EK:1396-10-01:0":{"b": ["Анексія Відіна", "ee1ae44b"], "d": ["Після перемоги під Нікополем анексували також Відін, останнє болгарське князівство.", "28f4258d"]},
"OLAYLAR_EK:1397-07-01:0":{"b": ["Перша анексія Карамана", "3cf07876"], "d": ["Завдяки перемозі при Акчаї землі Караманідів уперше приєднали до Османської держави (під час міжцарів'я вони відновляться).", "788bdca3"]},
"OLAYLAR_EK:1398-07-01:0":{"b": ["Приєднання узбережжя Джаніка: Самсун", "af9c40fa"], "d": ["У вакуумі, що утворився, коли Каді Бурханеддін потрапив у полон до Караюлюка Османа-бея з Ак-Коюнлу, Баязид Блискавичний спершу підпорядкував османському управлінню край Джанік на чорноморському узбережжі. Так Самсун і його околиці стали першим чорноморським портом династії. Лінію Сівас—Токат—Кайсері у внутрішніх землях приєднають через два тижні з фактичним розпадом держави Каді Бурханеддіна.", "4b2f9a80"]},
"OLAYLAR_EK:1399-09-01:0":{"b": ["Взяття Малатьї", "7cb6ae16"], "d": ["Було захоплено Малатью на мамлюцькому кордоні — один із кроків, що загострили напруження з Тимуром.", "3b7ba002"]},
"OLAYLAR_EK:1400-01-01:0":{"b": ["Тимур узяв Малатью й залишив її Караюлюку Осману — коли Тимур відійшов, її повернули Дулкадириди", "ad2ce7d8"], "d": ["Баязид Блискавичний, залишивши взяту 1399 року Малатью Насреддіну Мехмеду з роду Дулкадиридів, повернувся до Бурси. Тимур, який вступив в Анатолію 1400 року, взяв спершу Сівас та Ельбістан, а потім Малатью; місто та околиці пограбували, а управління ними залишили Караюлюку Осману, що перебував при Тимурі. Коли Тимур відійшов із краю, над Малатьєю знову запанували Дулкадириди; так османське панування скінчилося ще до Анкари.", "5889cce9"]},
"OLAYLAR_EK:1425-06-01:0":{"b": ["Повторна анексія західноанатолійських бейліків: Ментеше та Айдин", "aca30a48"], "d": ["Два егейські бейліки, відновлені під час міжцарів'я, за Мурада II остаточно приєднали до османських земель. За статтею TDV про Ментеше, Мурад II захопив землю Ментеше 827 (1424) року й ув'язнив двох братів, що стояли на чолі бейліку. За статтею ж про Айдинідів, бейлербей Анатолії Хамза-бей наказав схопити Джюнейда-бея, який знову вийшов із покори, і стратити його разом із родиною (829/1425-26), а землю Айдин перейшла до османів. Лицарі святого Іоанна, які з 1344 року тримали портову фортецю Ізміра, 1402 року втратили її на користь Тимура, і край повернувся під контроль Айдинідів; з цією анексією він також приєднався до османів. Земля Теке (Анталія) не є предметом цього запису: Текеїдів ліквідували окремо 1423 року. Ґерміян же приєднають 1429 року за заповітом.", "92fa8d97"]},
"OLAYLAR_EK:1430-03-29:0":{"b": ["Остаточне завоювання Салонік", "bc021768"], "d": ["Місто, що перебувало під венеційським управлінням, взяли штурмом; другий великий порт Румелії остаточно став османським. Інші місця, приєднані тоді ж: Кассандра (Кесендіре).", "8853e257"]},
"OLAYLAR_EK:1430-10-09:0":{"b": ["Здача Яніни", "ee45cb52"], "d": ["Яніна, осередок Епіру, здалася за угодою.", "1aad46c0"]},
"OLAYLAR_EK:1456-06-04:0":{"b": ["Завоювання Афін", "4f0f1bb2"], "d": ["Афінське герцогство припинило існування; на Акрополі підняли османський прапор. Інші місця, приєднані тоді ж: Фіви (Істефе), Лівадія.", "a912625d"]},
"OLAYLAR_EK:1459-06-20:0":{"b": ["Анексія Сербії (падіння Смедерева)", "75fd0a62"], "d": ["Смедерево, столиця Сербської деспотовини, здалося; Сербія стала османським санджаком.", "29bd2888"]},
"OLAYLAR_EK:1460-05-29:0":{"b": ["Завоювання Мореї", "7d5a3c18"], "d": ["Морейський деспотат ліквідували; півострів (крім венеційських фортець) перейшов під османське управління.", "14aba74c"]},
"OLAYLAR_EK:1461-06-01:0":{"b": ["Приєднання Синопа", "e03c2739"], "d": ["Джандаридський правитель Синопа здався без бою; відкрився шлях для Трапезундського походу. Інші місця, приєднані тоді ж: Кастамону, Бартин, Сафранболу. Стаття TDV про Джандаридів називає серед земель бейліку Джандаридів, анексованих 1461 року, також Болу, Ефлані та Тосью; в атласі ці три місця того ж дня записані як такі, що перейшли від Джандаридів до османів. Інші поселення, втрачені тоді ж: Караденіз-Ереглі, Деврек, Акчакоджа (землі Джандаридів).", "9ead5a1c"]},
"OLAYLAR_EK:1463-06-01:0":{"b": ["Падіння Боснійського королівства — боснійський похід Фатіха", "5362e3f2"], "d": ["Коли останній боснійський король Стефан Томашевич (1461-1463), покладаючись на підтримку Заходу, відмовився платити данину, його стали вважати таким, що перестав бути залежним правителем, і військо під проводом султана Мехмеда Фатіха ліквідувало Боснійське королівство за один похід. Короля схопили та стратили, королівство зникло, а в краї утворили Боснійський санджак. Проте падіння королівства — не те саме, що завоювання Боснії. Османське управління в рівнині існувало вже п'ятнадцять років: Ходидєд і Сараєвську рівнину взяли 1448 року, а прикордонне бейство Іси-бея виникло посеред королівства. Завоювання не скінчилося й 1463 року: Фочу взяли 1465-го, Ливно — 1469-го, Герцогство Герцеговину — 1483-го, Сребреницький банат — 1512-го, а Яйце й Баню-Луку на півночі вдалося взяти лише 1528 року, після Мохача: угорці створили на півночі Боснії банат, який протримався шістдесят п'ять років після 1463-го. На цю дату прямо змінило власника місце Травнік; Яйце ж на цю дату перейшло не до османів, а до Угорщини.", "5ac16344"]}
});
